export const CURRICULO_ESTRUTURADO = {"Ciências": [{"a": "6", "t": "1", "c": "EF06CI01/ES", "e": "Matéria e Energia", "h": "Observar, reconhecer e identificar características de diferentes materiais e suas misturas, registrando suas observações antes e após a mistura, por meio de diferentes mídias e linguagens, classificando essas misturas como homogêneas ou heterogêneas (óleo, água e areia entre outros).", "o": "Misturas homogêneas e heterogêneas."}, {"a": "6", "t": "1", "c": "EF06CI02/ES", "e": "Matéria e Energia", "h": "Identificar evidências de transformações químicas a partir do resultado de práticas experimentais em que produtos originados de uma mistura sejam diferentes das substâncias iniciais, registrando suas observações antes e após da mistura, por meio de diferentes mídias e linguagens e discutindo sua aplicabilidade e influência na atividade humana e no meio ambiente.", "o": "Transformações químicas."}, {"a": "6", "t": "1", "c": "EF06CI03/ES", "e": "Matéria e Energia", "h": "Identificar processos de separação de materiais (como a produção de sal de cozinha, a destilação de petróleo, o tratamento de água e/ou efluentes, a produção do álcool, entre outros) e selecionar os métodos mais adequados para a separação de diferentes sistemas heterogêneos, relacionando sistemas produtivos locais ou regionais que utilizem a separação de materiais no seu processo, de forma a propor ações coletivas que promovam a consciência ambiental e um modo de vida sustentável.", "o": "Separação de materiais."}, {"a": "6", "t": "1", "c": "EF06CI04/ES", "e": "Matéria e Energia", "h": "Identificar os tipos de medicamentos (fitoterápicos, alopáticos, manipulados, entre outros) e de outros materiais sintéticos (fios de nylon, plásticos etc.) e associar a sua produção ao desenvolvimento científico e tecnológico, reconhecendo benefícios e avaliando impactos socioambientais, ao analisar as consequências de seu uso e descarte em sua região e no mundo.", "o": "Materiais sintéticos."}, {"a": "6", "t": "1", "c": "EF06CI15/ES", "e": "Matéria e Energia", "h": "Reconhecer que o movimento de pessoas e objetos possuem diferentes explicações expressas ao longo da história, comparando-as com interpretações espontâneas, não científicas, e não raro, encontráveis ainda hoje.", "o": "A ação de forças e o estado de movimento."}, {"a": "6", "t": "1", "c": "EF06CI16/ES", "e": "Matéria e Energia", "h": "Relacionar o estado de movimento de pessoas e objetos à ação de forças aplicadas, identificando as situações de equilíbrio estático e equilíbrio dinâmico", "o": "Condições de equilíbrio mecânico estático e dinâmico."}, {"a": "6", "t": "2", "c": "EF06CI05/ES", "e": "Vida e Evolução", "h": "Identificar e explicar a organização básica das células e seu papel como unidade estrutural e funcional dos seres vivos, representando-as por meio de modelos e simulações e reconhecendo-as como unidade básica da vida (teoria celular).", "o": "Célula como unidade da vida"}, {"a": "6", "t": "2", "c": "EF06CI06/ES", "e": "Vida e Evolução", "h": "Identificar e reconhecer os diferentes níveis de organização dos seres vivos (tecidos, órgãos e sistemas), por meio da análise de ilustrações e/ou representações tridimensionais, incluindo o uso de mídias digitais, comparando as suas características, de modo a classificá-los em uma perspectiva evolutiva e concluir que são constituídos de um complexo arranjo de sistemas com diferentes níveis de organização.", "o": "Níveis de organização dos seres vivos."}, {"a": "6", "t": "2", "c": "EF06CI07", "e": "Vida e Evolução", "h": "Justificar o papel do sistema nervoso na coordenação das ações motoras e sensoriais do corpo, com base na análise de suas estruturas básicas e respectivas funções.", "o": "Sistema nervoso."}, {"a": "6", "t": "2", "c": "EF06CI08/ES", "e": "Vida e Evolução", "h": "Explicar a importância da visão (captação e interpretação das imagens) na interação dos seres vivos com o meio, identificando as partes que compõem o olho em diferentes seres vivos, explicando suas funções e identificar as diferentes anomalias da visão e suas formas de correção.", "o": "O Sentido da visão."}, {"a": "6", "t": "2", "c": "EF06CI09/ES", "e": "Vida e Evolução", "h": "Identificar as partes e estruturas do sistema esquelético e muscular, compreendendo e explicando suas funções, de modo a deduzir que a estrutura, a sustentação e a movimentação dos animais resultam da interação entre esses sistemas, em conjunto com o sistema nervoso.", "o": "Sistemas esquelético e muscular"}, {"a": "6", "t": "3", "c": "EF06CI10/ES", "e": "Vida e Evolução", "h": "Identificar e classificar as substâncias psicoativas lícitas e ilícitas, reconhecendo os seus efeitos no organismo humano e classificando-as como depressoras, estimulantes ou alucinógenas, de modo a explicar como o funcionamento do sistema nervoso pode ser afetado por essas substâncias e discutir o seu uso em diferentes culturas, bem como os seus efeitos sociais na atualidade.", "o": "Efeitos de substâncias psicoativas sobre o sistema nervoso. Práticas experimentais de Ciências Sugestões de materiais"}, {"a": "6", "t": "3", "c": "EF06CI11/ES", "e": "Terra e Universo", "h": "Identificar as diferentes camadas que estruturam o planeta Terra (da estrutura interna à atmosfera) e suas principais características, diferenciando-as e descrevendo-as por meio de modelos bidimensionais e tridimensionais e reconhecer os distintos modelos representativos do planeta Terra em diferentes épocas e culturas, compreendendo o impacto do desenvolvimento científico na construção e reconstrução desses modelos.", "o": "Estrutura da Terra."}, {"a": "6", "t": "3", "c": "EF06CI12/ES", "e": "Terra e Universo", "h": "Identificar diferentes tipos de rocha, relacionando suas características à formação de fósseis em diferentes períodos geológicos, segundo uma perspectiva evolutiva que os encare como evidência e referência da vida no passado.", "o": "Tipos de rochas e formação de fósseis."}, {"a": "6", "t": "3", "c": "EF06CI13/ES", "e": "Terra e Universo", "h": "Selecionar argumentos a partir da identificação, da comparação e do reconhecimento de evidências que expliquem os modelos representativos da forma real da Terra.", "o": "Forma da Terra."}, {"a": "6", "t": "3", "c": "EF06CI14/ES", "e": "Terra e Universo", "h": "Inferir que as variações da radiação solar em cada região, ao longo do dia e em diferentes períodos do ano, evidenciadas pelas mudanças que ocorrem na projeção das sombras de diferentes objetos (gnômon, árvores, edifícios entre outros) se correlacionam com os movimentos relativos entre a Terra e o Sol e representar tais movimentos por meio de modelos bidimensionais e tridimensionais.", "o": "Movimentos relativos entre a Terra e o sol. Práticas experimentais de Ciências Sugestões de materiais"}, {"a": "7", "t": "1", "c": "EF07CI01/ES", "e": "Matéria e Energia", "h": "Identificar e compreender o que são máquinas simples e discutir a sua aplicação, ao longo da história, de forma a propor soluções e invenções de recursos ou equipamentos mecânicos que facilitem a realização de tarefas cotidianas. 7º ano", "o": "Máquinas simples."}, {"a": "7", "t": "1", "c": "EF07CI02/ES", "e": "Matéria e Energia", "h": "Diferenciar temperatura, calor e sensação térmica nas diferentes situações de equilíbrio termodinâmico cotidianas, reconhecendo as condições para existência de fluxo térmico e de equilíbrio termodinâmico e identificando formas de medir a temperatura de diferentes materiais e substâncias em diferentes condições.", "o": "Temperatura e calor."}, {"a": "7", "t": "1", "c": "EF07CI03/ES", "e": "Matéria e Energia", "h": "Reconhecer e classificar modos de propagação de calor entre diferentes meios e utilizar esse conhecimento para justificar a utilização de determinados materiais (condutores e isolantes) na vida cotidiana, explicar o princípio de funcionamento de alguns equipamentos (garrafa térmica, coletor solar etc.) e/ou construir soluções tecnológicas a partir desse conhecimento. 7º ano", "o": "Propagação do calor."}, {"a": "7", "t": "1", "c": "EF07CI04-a/ES", "e": "Matéria e Energia", "h": "Avaliar o papel do equilíbrio termodinâmico para a manutenção da vida na Terra, identificando as características ambientais necessárias para que a vida ocorra e propor a construção de modelos representativos, em diferentes mídias e formas de expressão, nos quais sejam identificadas as condições necessárias para a manutenção do equilíbrio ambiental.", "o": "Termodinâmica e Meio Ambiente."}, {"a": "7", "t": "1", "c": "EF07CI04-b/ES", "e": "Matéria e Energia", "h": "Identificar e compreender o que são as máquinas térmicas, construindo protótipos e/ou modelos bidimensionais e tridimensionais, de forma a entender como funcionam e avaliar o papel do equilíbrio termodinâmico em seu funcionamento.", "o": "Máquinas térmicas."}, {"a": "7", "t": "1", "c": "EF07CI05", "e": "Matéria e Energia", "h": "Discutir o uso de diferentes tipos de combustível e máquinas térmicas ao longo do tempo, para avaliar avanços, questões econômicas e problemas socioambientais causados pela produção e uso desses materiais e máquinas. 7º ano", "o": "História dos combustíveis e das máquinas térmicas."}, {"a": "7", "t": "1", "c": "EF07CI06", "e": "Matéria e Energia", "h": "Discutir e avaliar mudanças econômicas, culturais e sociais, tanto na vida cotidiana quanto no mundo do trabalho, decorrentes do desenvolvimento de novos materiais e tecnologias (como automação e informatização).", "o": "Desenvolvimento tecnológico. 7º ano"}, {"a": "7", "t": "2", "c": "EF07CI07", "e": "Vida e Evolução", "h": "Caracterizar os principais ecossistemas brasileiros quanto à paisagem, à quantidade de água, ao tipo de solo, à disponibilidade de luz solar, à temperatura etc., correlacionando essas características à flora e fauna específicas.", "o": "Ecossistemas brasileiros."}, {"a": "7", "t": "2", "c": "EF07CI08", "e": "Vida e Evolução", "h": "Avaliar como os impactos provocados por catástrofes naturais ou mudanças nos componentes físicos, biológicos ou sociais de um ecossistema afetam suas populações, podendo ameaçar ou provocar a extinção de espécies, alteração de hábitos, migração etc.", "o": "Fenômenos naturais e impactos socioambientais."}, {"a": "7", "t": "2", "c": "EF07CI09", "e": "Vida e Evolução", "h": "Interpretar as condições de saúde da comunidade, da cidade ou do estado, com base na análise e na comparação de indicadores de saúde (como taxa de mortalidade infantil, cobertura de saneamento básico e incidência de doenças de veiculação hídrica, atmosférica entre outras) e dos resultados de políticas públicas destinadas à saúde.", "o": "Programas e indicadores de saúde pública."}, {"a": "7", "t": "2", "c": "EF07CI10", "e": "Vida e Evolução", "h": "Argumentar sobre a importância da vacinação para a saúde pública, com base em informações sobre a maneira como a vacina atua no organismo e o papel histórico da vacinação para a manutenção da saúde ndividual e coletiva e para a erradicação de doenças.", "o": "Vacinação e saúde pública."}, {"a": "7", "t": "2", "c": "EF07CI11/ES", "e": "Vida e Evolução", "h": "Analisar o desenvolvimento científico e tecnológico o longo da história da humanidade, considerando indicadores ambientais e sociais, de modo a identificar e reconhecer avanços no tratamento e nas medidas de prevenção de doenças, na melhoria da saúde e da qualidade de vida das pessoas, incluindo a intervenção no modo e nos hábitos de vida.", "o": "Ciência, tecnologia e saúde."}, {"a": "7", "t": "3", "c": "EF07CI12/ES", "e": "Terra e Universo", "h": "Demonstrar que o ar é uma mistura de gases, identificando a sua composição, e discutir fenômenos naturais ou antrópicos que podem alterar essa composição e/ou interferir na saúde coletiva e no equilíbrio dos ecossistemas e em sua região.", "o": "Composição do ar."}, {"a": "7", "t": "3", "c": "EF07CI13", "e": "Terra e Universo", "h": "Descrever o mecanismo natural do efeito estufa, seu papel fundamental para o desenvolvimento da vida na Terra, discutir as ações humanas responsáveis pelo seu aumento artificial (queima dos combustíveis fósseis, desmatamento, queimadas e outras formas de interferência). E selecionar e implementar propostas para a reversão ou controle desse quadro.", "o": "Efeito estufa"}, {"a": "7", "t": "3", "c": "EF07CI14", "e": "Terra e Universo", "h": "Justificar a importância da camada de ozônio para a vida na Terra, identificando os fatores que aumentam ou diminuem sua presença na atmosfera, e discutir propostas individuais e coletivas para sua preservação.", "o": "Camada de ozônio."}, {"a": "7", "t": "3", "c": "EF07CI15/ES", "e": "Terra e Universo", "h": "Interpretar fenômenos naturais (como vulcões, terremotos e tsunamis), por meio de textos, artigos e dados, e justificar a rara ocorrência desses fenômenos no Brasil, com base no modelo das placas tectônicas.", "o": "Fenômenos naturais (vulcões, terremotos e tsunamis)."}, {"a": "7", "t": "3", "c": "EF07CI16/ES", "e": "Terra e Universo", "h": "Justificar o formato das costas brasileira e africana com base na teoria da deriva dos continentes, construindo modelos explicativos e ilustrativos que relacionem a costa brasileira e a africana a partir do movimento das massas continentais ao longo do tempo geológico do planeta Terra e de evidências paleoclimáticas, geológicas, geofísicas e biogeográficas.", "o": "Placas tectônicas e deriva continental"}, {"a": "8", "t": "1", "c": "EF08CI01/ES", "e": "Matéria e Energia", "h": "Identificar que a energia elétrica utilizada em residências, comunidades ou cidades pode ser obtida de fontes renováveis e/ou não renováveis, classificando-a de acordo com sua origem (eólica, hidrelétrica, solar, geotérmica, biomassa etc.).", "o": "Energia elétrica."}, {"a": "8", "t": "1", "c": "EF08CI02/ES", "e": "Matéria e Energia", "h": "Construir circuitos elétricos simples, a partir da compreensão de como ocorre a corrente elétrica, identificando a função dos elementos de circuito mais comuns (resistores, capacitores, geradores, etc.), reconhecendo medidas básicas de segurança ao lidar com eletricidade, e comparar as características desses circuitos com as dos circuitos elétricos residenciais.", "o": "Circuitos elétricos. Práticas experimentais de Ciências Sugestões de materiais"}, {"a": "8", "t": "1", "c": "EF08CI03", "e": "Matéria e Energia", "h": "Classificar equipamentos elétricos residenciais (chuveiro, ferro, lâmpadas, TV, rádio, geladeira etc.) de acordo com o tipo de transformação de energia (da energia elétrica para a térmica, luminosa, sonora e mecânica, por exemplo).", "o": "Transformação de energia."}, {"a": "8", "t": "1", "c": "EF08CI04", "e": "Matéria e Energia", "h": "Calcular o consumo de eletrodomésticos a partir dos dados de potência (descritos no próprio equipamento) e tempo médio de uso para avaliar o impacto de cada equipamento no consumo doméstico mensal.", "o": "Cálculo de consumo de energia elétrica."}, {"a": "8", "t": "1", "c": "EF08CI05", "e": "Matéria e Energia", "h": "Propor ações coletivas para otimizar o uso de energia elétrica em sua escola e/ou comunidade, com base na seleção de equipamentos segundo critérios de sustentabilidade (consumo de energia e eficiência energética) e hábitos de consumo responsável.", "o": "Uso consciente de energia elétrica."}, {"a": "8", "t": "1", "c": "EF08CI06", "e": "Matéria e Energia", "h": "Discutir e avaliar usinas de geração de energia elétrica (termelétricas, hidrelétricas, eólicas etc.), suas semelhanças e diferenças, seus impactos socioambientais, e como essa energia chega e é usada em sua cidade, comunidade, casa ou escola.", "o": "Uso consciente de energia elétrica."}, {"a": "8", "t": "2", "c": "EF08CI07/ES", "e": "Vida e Evolução", "h": "Comparar diferentes processos reprodutivos em plantas e animais, diferenciando e descrevendo as partes que compõem seus sistemas reprodutores e reconhecendo suas funções, bem como aspectos da reprodução sexuada e assexuada, dos tipos de fertilização, do desenvolvimento e da existência de cuidado parental, e explicar o papel dos mecanismos reprodutivos na conservação ou modificação de características que envolvem a adaptação dos seres vivos em um processo evolutivo. 8º ano", "o": "Mecanismos reprodutivos."}, {"a": "8", "t": "2", "c": "EF08CI08/ES", "e": "Vida e Evolução", "h": "Analisar e explicar as transformações que ocorrem na puberdade, considerando a atuação dos hormônios sexuais e do sistema nervoso, identificando e descrevendo as mudanças físicas e psicológicas que ocorrem nessa fase da vida, assim como as questões relacionadas à saúde que lhe são específicas e reconhecendo a diversidade de desenvolvimento e de construção de identidades sociais e culturais (tradições e ritos de passagem).", "o": "Adolescência e puberdade."}, {"a": "8", "t": "2", "c": "EF08CI09", "e": "Vida e Evolução", "h": "Comparar o modo de ação e a eficácia dos diversos métodos contraceptivos e justificar a necessidade de compartilhar a responsabilidade na escolha e na utilização do método mais adequado à prevenção da gravidez precoce e indesejada e de Doenças Sexualmente Transmissíveis (DST).", "o": "Métodos contraceptivos. 8º ano"}, {"a": "8", "t": "2", "c": "EF08CI10/ES", "e": "Vida e Evolução", "h": "Identificar os principais sintomas, modos de transmissão e tratamento de algumas DST (Gonorreia, Sífilis, HPV, Aids, Herpes, etc.), e discutir estratégias e selecionar métodos de prevenção mais adequados às diferentes DST, envolvendo a responsabilidade e consciência sobre a sua saúde sexual.", "o": "Doenças Sexualmente Transmissíveis."}, {"a": "8", "t": "2", "c": "EF08CI11/ES", "e": "Vida e Evolução", "h": "Selecionar argumentos que evidenciem as múltiplas dimensões da sexualidade humana (biológica, sociocultural, afetiva e ética), reconhecendo, compreendendo e discutindo aspectos como o cuidado e o respeito a si mesmo e ao outro, a construção da identidade social e cultural, a afetividade e a compreensão dos aspectos culturais envolvidos na sexualidade humana.", "o": "Sexualidade humana."}, {"a": "8", "t": "3", "c": "EF08CI12/ES", "e": "Terra e Universo", "h": "Justificar a ocorrência das fases da Lua e dos eclipses lunares e solares, a partir da observação do céu, da leitura de textos e artigos científicos e da utilização de recursos digitais, representando o sistema sol, Terra e lua por meio de modelos bidimensionais e tridimensionais.", "o": "Sistema sol, Terra e lua."}, {"a": "8", "t": "3", "c": "EF08CI13/ES", "e": "Terra e Universo", "h": "Compreender, descrever e ilustrar os movimentos de rotação e translação da Terra, representando o sistema sol e Terra por meio de modelos bidimensionais e tridimensionais, relacionando o movimento orbital da Terra e a sua exposição aos raios solares à ocorrência das estações do ano e explicar a influência desses fenômenos em seu cotidiano e sobre o modo de vida na Terra.", "o": "Movimento orbital da Terra e estações do ano."}, {"a": "8", "t": "3", "c": "EF08CI14/ES", "e": "Terra e Universo", "h": "Compreender e explicar o deslocamento das massas de ar e sua relação com as diferenças de temperatura e pressão existentes na atmosfera terrestre e na dinâmica da temperatura nos oceanos, de modo a relacionar climas regionais aos padrões de circulação atmosférica e oceânica e ao aquecimento desigual causado pela forma e pelos movimentos da Terra.", "o": "Tempo e clima."}, {"a": "8", "t": "3", "c": "EF08CI15/ES", "e": "Terra e Universo", "h": "Identificar as principais variáveis envolvidas na previsão do tempo e simular situações nas quais elas possam ser medidas, associando a intervenção humana às mudanças dessas variáveis, com destaque para as que interferem na paisagem e na agricultura bem como para as consequências que acarretam no clima local e global.", "o": "Variáveis meteorológicas."}, {"a": "8", "t": "3", "c": "EF08CI16", "e": "Terra e Universo", "h": "Discutir iniciativas que contribuam para restabelecer o equilíbrio ambiental a partir da identificação de alterações climáticas regionais e globais provocadas pela intervenção humana.", "o": "Alterações climáticas e equilíbrio ambiental."}, {"a": "9", "t": "1", "c": "EF09CI01/ES", "e": "Matéria e Energia", "h": "Explicar estados físicos da matéria e suas transformações, com base no modelo de constituição submicroscópica, estimulando a interpretação de dados para o levantamento e desenvolvimento de hipóteses sobre a aplicação de determinados processos na solução de problemas no cotidiano e no sistema produtivo.", "o": "Estados físicos da matéria e suas transformações."}, {"a": "9", "t": "1", "c": "EF09CI02/ES", "e": "Matéria e Energia", "h": "Comparar quantidades de reagentes e produtos envolvidos em transformações químicas do cotidiano e em geral, estabelecendo a proporção entre as suas massas utilizando atividades investigativas experimentais para identificar e representar substâncias simples e compostas e explorar símbolos, fórmulas e equações, com ênfase na proporção de massas.", "o": "Aspectos quantitativos das transformações químicas."}, {"a": "9", "t": "1", "c": "EF09CI03/ES", "e": "Matéria e Energia", "h": "Identificar modelos que descrevem a estrutura da matéria (constituição do átomo e composição de moléculas simples), descrevendo-os e representando-os em diferentes mídias, linguagens e formas de expressão e reconhecer a sua evolução histórica.", "o": "Estrutura da matéria."}, {"a": "9", "t": "1", "c": "EF09CI04/ES", "e": "Matéria e Energia", "h": "Planejar e executar experimentos que evidenciem fenômenos relacionados à decomposição da luz e à percepção de cores, investigando a relação do espectro eletromagnético com a percepção das cores em diferentes materiais do cotidiano, quando expostos a diferentes fontes de iluminação e reconhecer como o sistema visual dos seres vivos interpreta as cores.", "o": "A luz como radiação eletromagnética visível."}, {"a": "9", "t": "1", "c": "EF09CI05/ES", "e": "Matéria e Energia", "h": "Investigar os principais mecanismos envolvidos na transmissão e recepção de imagem e som que revolucionaram os sistemas de comunicação humana, identificando, analisando, categorizando e explicando os processos de transmissão e recepção de imagem e som, relacionando-os às radiações eletromagnéticas e reconhecendo a evolução dos meios de comunicação e suas implicações na vida humana.", "o": "Uso das radiações telecomunicações. eletromagnéticas nas"}, {"a": "9", "t": "1", "c": "EF09CI06/ES", "e": "Matéria e Energia", "h": "Classificar as radiações eletromagnéticas por suas frequências, fontes e aplicações, relacionar as ondas eletromagnéticas ao seu uso em diferentes tecnologias e avaliar os desdobramentos da aplicação tecnológica das radiações em uma perspectiva socioambiental.", "o": "Características das radiações eletromagnéticas."}, {"a": "9", "t": "1", "c": "EF09CI07", "e": "Matéria e Energia", "h": "Discutir e avaliar o papel do avanço tecnológico na aplicação da radiação eletromagnética no diagnóstico (raios-X, ultrassom, ressonância nuclear magnética) e tratamento de doenças (radioterapia, cirurgia ótica a laser etc.).", "o": "Aplicações das radiações eletromagnéticas na saúde."}, {"a": "9", "t": "2", "c": "EF09CI08/ES", "e": "Vida e Evolução", "h": "Associar os gametas à transmissão das características hereditárias, identificando as estruturas celulares, do DNA e os cromossomos, por meio de exemplos e modelos ilustrativos, de modo a reconhecer os princípios da hereditariedade, para estabelecer relações entre ancestrais e descendentes, reconhecendo suas características físicas como hereditárias, congênitas, adquiridas ou genéticas.", "o": "Hereditariedade."}, {"a": "9", "t": "2", "c": "EF09CI09", "e": "Vida e Evolução", "h": "Discutir as ideias de Mendel sobre hereditariedade (fatores hereditários, segregação, gametas, fecundação), considerando-as para resolver problemas envolvendo a transmissão de características hereditárias em diferentes organismos.", "o": "Leis de Mendel."}, {"a": "9", "t": "2", "c": "EF09CI10", "e": "Vida e Evolução", "h": "Comparar as ideias evolucionistas de Lamarck e Darwin apresentadas em textos científicos e históricos, identificando semelhanças e diferenças entre essas ideias e compreendendo a sua importância para explicar a diversidade biológica.", "o": "Ideias evolucionistas."}, {"a": "9", "t": "2", "c": "EF09CI11", "e": "Vida e Evolução", "h": "Discutir a evolução e a diversidade das espécies com base na atuação da seleção natural sobre as variantes de uma mesma espécie, resultantes de processo reprodutivo.", "o": "Variabilidade genética e seleção natural. 9º ano"}, {"a": "9", "t": "2", "c": "EF09CI12/ES", "e": "Vida e Evolução", "h": "Justificar a importância das unidades de conservação para a preservação da biodiversidade e do patrimônio nacional, considerando os diferentes tipos de unidades (parques, reservas e florestas nacionais), as populações humanas e atividades a eles relacionadas, reconhecendo as legislações e as regulamentações que asseguram existência das unidades de conservação, de modo a propor soluções sustentáveis para a composição dessas unidades em diferentes ecossistemas.", "o": "Preservação da biodiversidade."}, {"a": "9", "t": "2", "c": "EF09CI13", "e": "Vida e Evolução", "h": "Propor iniciativas individuais e coletivas para a solução de problemas ambientais da cidade ou da comunidade, com base na análise de ações sustentáveis bemsucedidas.", "o": "Responsabilidade Socioambiental."}, {"a": "9", "t": "3", "c": "EF09CI14", "e": "", "h": "Descrever a composição e a estrutura do sistema solar (sol, planetas rochosos, planetas gigantes gasosos e corpos menores), assim como a localização do sistema solar na nossa Galáxia (a Via Láctea) e dela no universo (apenas uma galáxia dentre bilhões).", "o": "Composição, estrutura e localização do sistema solar no universo."}, {"a": "9", "t": "3", "c": "EF09CI15", "e": "Terra e Universo", "h": "Relacionar diferentes leituras do céu e explicações sobre a origem da Terra, do sol ou do sistema solar às necessidades de distintas culturas (a agricultura, a caça, os mitos, as formas e instrumentos de orientação espacial e temporal entre outros.).", "o": "Astronomia e cultura."}, {"a": "9", "t": "3", "c": "EF09CI16/ES", "e": "Terra e Universo", "h": "Selecionar argumentos sobre a viabilidade da sobrevivência humana fora da Terra, com base nas condições necessárias à vida, nas características dos planetas, nas distâncias e nos tempos envolvidos em viagens interplanetárias e interestelares e analisar se esses elementos podem ser encontrados na zona habitável do sistema solar, a partir de informações obtidas sobre outros astros, considerando aspectos da exploração espacial que desafiaram o modo de vida que se desenvolveu na Terra sob condições adversas, como radiação, suporte à vida, tempo, entre outros.", "o": "Vida humana fora da Terra."}, {"a": "9", "t": "3", "c": "EF09CI17", "e": "Terra e Universo", "h": "Analisar o ciclo evolutivo do sol (nascimento, vida e morte) baseado no conhecimento das etapas de evolução de estrelas de diferentes dimensões e os efeitos desse processo no nosso planeta.", "o": "Evolução estelar."}], "Artes": [{"a": "6", "t": "1", "c": "EF69AR01-06/ES", "e": "", "h": "Pesquisar, apreciar e analisar formas distintas das artes visuais que identifiquem a formação do povo brasileiro, tradicionais e contemporâneas, em obras de artistas brasileiros e estrangeiros de diferentes épocas e em diferentes matrizes estéticas e culturais, de modo a ampliar a experiência com diferentes contextos e práticas artístico-visuais e cultivar a percepção, o imaginário, a capacidade de simbolizar e o repertório imagético.", "o": "• Contextos e práticas."}, {"a": "6", "t": "1", "c": "EF69AR02-06/ES", "e": "", "h": "Pesquisar e analisar diferentes estilos visuais nas obras da arte brasileira, contextualizando-os com estilos internacionais no tempo e no espaço.", "o": "• Elementos da linguagem."}, {"a": "6", "t": "1", "c": "EF69AR03-06/ES", "e": "", "h": "Analisar situações nas quais as linguagens das artes visuais se integram às linguagens audiovisuais (cinema, animações, vídeos etc.), gráficas (capas de livros, ilustrações de textos diversos etc.), cenográficas, coreográficas, musicais etc., principalmente na produção da arte brasileira.", "o": "• Contextos e práticas"}, {"a": "6", "t": "1", "c": "EF69AR04", "e": "", "h": "Analisar os elementos constitutivos das artes visuais (ponto, linha, forma, direção, cor, tom, escala, dimensão, espaço, movimento etc.) na apreciação de diferentes produções artísticas.", "o": "• Elementos da Linguagem."}, {"a": "6", "t": "1", "c": "EF69AR05-06/ES", "e": "", "h": "Experimentar e analisar diferentes formas de expressão artística (desenho, pintura, colagem, quadrinhos, dobradura, escultura, modelagem, instalação, vídeo, fotografia, performance, etc.), percebendo as potencialidades e possibilidades de cada meio, materiais e instrumentos utilizados por diferentes artistas brasileiros.", "o": "• Materialidades."}, {"a": "6", "t": "1", "c": "EF69AR06-06/ES", "e": "", "h": "Desenvolver processos de criação em artes visuais, com base em temas ou interesses artísticos presentes na arte brasileira, de modo individual, coletivo e colaborativo, fazendo uso de materiais, instrumentos e recursos convencionais, alternativos e digitais, propiciando novos desafios e possibilidades na construção de uma narrativa própria.", "o": "• Processos de criação."}, {"a": "6", "t": "1", "c": "EF69AR07-06/ES", "e": "", "h": "Dialogar com princípios conceituais, proposições temáticas, repertórios imagéticos e processos de criação nas suas produções visuais, aprofundando a poética pessoal e ampliando o vocabulário próprio.", "o": "• Processos de criação."}, {"a": "6", "t": "1", "c": "EF69AR08-06/ES", "e": "", "h": "Diferenciar as categorias artísticas, artesão, produtor cultural, curador, designer, entre outras, estabelecendo relações entre os profissionais do sistema das artes visuais, conhecendo a função de cada um desses agentes na elaboração de saraus, exposições, eventos culturais, etc.", "o": "• Sistemas da linguagem."}, {"a": "6", "t": "1", "c": "EF69AR31-06/ES", "e": "", "h": "Relacionar as práticas artísticas às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética, percebendo a formação da arte brasileira na identidade do povo que constitui essa nação.", "o": "• Contextos e práticas."}, {"a": "6", "t": "1", "c": "EF69AR33-06/ES", "e": "", "h": "Analisar aspectos históricos, sociais e políticos da produção artística, problematizando as narrativas eurocêntricas e as diversas categorizações da arte (arte, artesanato, folclore, design etc.), percebendo e respeitando a diversidade étnica na formação do povo brasileiro.", "o": "• Matrizes estéticas e culturais."}, {"a": "6", "t": "1", "c": "EF69AR34-06/ES", "e": "", "h": "Analisar e valorizar o patrimônio cultural, material e imaterial, de culturas diversas, em especial a brasileira, incluindo suas matrizes indígenas, africanas e europeias, de diferentes épocas, e favorecendo a construção de vocabulário e repertório relativos às diferentes linguagens artísticas, participando da identificação do que constitui o patrimônio material, imaterial, histórico, artístico e natural.", "o": "• Patrimônio cultural."}, {"a": "6", "t": "1", "c": "EF69AR35-06/ES", "e": "", "h": "Identificar e manipular diferentes tecnologias e recursos digitais para acessar, apreciar, produzir, registrar e compartilhar práticas e repertórios artísticos, de modo reflexivo, ético e responsável, utilizando recursos tecnológicos para ressignificar a arte brasileira.", "o": "• Arte e tecnologia."}, {"a": "6", "t": "2", "c": "EF69AR09-06/ES", "e": "", "h": "Pesquisar e analisar diferentes formas de expressão, representação e encenação da dança, reconhecendo e apreciando composições de dança de artistas e grupos brasileiros e estrangeiros, em destaque para apreciação de grupos e dançarinos brasileiros nos diferentes contextos e épocas.", "o": "• Contextos e práticas."}, {"a": "6", "t": "2", "c": "EF69AR10-06/ES", "e": "", "h": "Observar e explorar elementos constitutivos do movimento cotidiano e do movimento dançado, abordando, criticamente, o desenvolvimento das formas da dança em sua história tradicional e contemporânea, percebendo os significados desses elementos na dança brasileira.", "o": "• Elementos da linguagem."}, {"a": "6", "t": "2", "c": "EF69AR16-06/ES", "e": "", "h": "Analisar criticamente, por meio da apreciação musical, usos e funções da música em seus contextos de produção e circulação, principalmente no que diz respeito à diversidade musical brasileira, relacionando as práticas musicais às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética.", "o": "• Contextos e práticas."}, {"a": "6", "t": "2", "c": "EF69AR17-06/ES", "e": "", "h": "Explorar e analisar, criticamente, diferentes meios e equipamentos culturais de circulação da música e do conhecimento musical produzido no Brasil.", "o": "• Contextos e práticas."}, {"a": "6", "t": "2", "c": "EF69AR18-06/ES", "e": "", "h": "Reconhecer e apreciar o papel de músicos e grupos de música brasileiros e estrangeiros que contribuíram para o desenvolvimento de formas e gêneros musicais, evidenciando as transformações da música ao longo do tempo.", "o": "• Contextos e práticas."}, {"a": "6", "t": "2", "c": "EF69AR19-06/ES", "e": "", "h": "Identificar e analisar diferentes estilos musicais, a fim de ampliar o repertório, contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética musical.", "o": "• Contextos e práticas."}, {"a": "6", "t": "2", "c": "EF69AR20-06/ES", "e": "", "h": "Explorar e analisar elementos constitutivos da música (altura, intensidade, timbre, melodia, ritmo etc.), por meio de recursos naturais e tecnológicos (games e plataformas digitais), jogos, canções e práticas diversas de composição/criação, execução e apreciação musicais, ampliando a percepção dos parâmetros do som e os elementos básicos da música.", "o": "• Elementos da linguagem."}, {"a": "6", "t": "2", "c": "EF69AR21-06/ES", "e": "", "h": "Explorar e analisar fontes e materiais sonoros em práticas de composição/criação, execução e apreciação musical, reconhecendo timbres e características de instrumentos musicais diversos característicos da cultura brasileira.", "o": "• Materialidades."}, {"a": "6", "t": "2", "c": "EF69AR22-06/ES", "e": "", "h": "Explorar e identificar diferentes formas de registro musical não convencional (como partituras criativas e procedimentos da música contemporânea), bem como procedimentos e técnicas de registro em áudio e audiovisual e reconhecer os princípios da notação musical convencional.", "o": "• Notação e registro musical."}, {"a": "6", "t": "2", "c": "EF69AR23-06/ES", "e": "", "h": "Explorar e criar improvisações, composições, arranjos, jingles, trilhas sonoras, entre outros, utilizando vozes, sons corporais e/ou instrumentos acústicos ou eletrônicos, convencionais ou não convencionais, expressando ideias musicais de maneira individual, coletiva e colaborativa. Além disso, estimular-se para um fazer musical espontâneo e autêntico, com respeito e valorização dos elementos que constituem a diversidade cultural brasileira.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR11-06/ES", "e": "", "h": "Experimentar e analisar os fatores de movimento (tempo, peso, fluência e espaço) como elementos que, combinados, geram as ações corporais e o movimento dançado, ampliando seu próprio repertório.", "o": "• Elementos da linguagem."}, {"a": "6", "t": "3", "c": "EF69AR12-06/ES", "e": "", "h": "Investigar e experimentar procedimentos de improvisação e criação do movimento como fonte para a construção de vocabulários e repertórios próprios, pesquisando, de maneira autônoma e /ou colaborativa, formas expressivas de dança.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR13-06/ES", "e": "", "h": "Investigar e vivenciar brincadeiras, jogos e danças coletivas, sobretudo as brasileiras, além de outras práticas de dança de diferentes matrizes estéticas e culturais como referência para a criação e a composição de danças autorais, individualmente e em grupo.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR14-06/ES", "e": "", "h": "Analisar e experimentar diferentes elementos (figurino, iluminação, cenário, trilha sonora etc.) e espaços (convencionais e não convencionais) para composição cênica e apresentação coreográfica, investigando e analisando os elementos e espaços da dança brasileira.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR15-06/ES", "e": "", "h": "Discutir as experiências pessoais e coletivas em dança vivenciadas na escola e em outros contextos, problematizando estereótipos e preconceitos, apreciando estilos de danças brasileiras de diferentes épocas.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR24-06/ES", "e": "", "h": "Reconhecer e apreciar artistas e grupos de teatro brasileiros e estrangeiros de diferentes épocas, investigando os modos de criação, produção, divulgação, circulação e organização da atuação profissional em teatro, além de pesquisar a formação do povo brasileiro na produção teatral.", "o": "• Contextos e práticas."}, {"a": "6", "t": "3", "c": "EF69AR25-06/ES", "e": "", "h": "Identificar e analisar diferentes estilos cênicos (tragédia clássica, tragédia moderna, comédia clássica, comédia moderna, entre outros), a fim de ampliar o repertório, contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética teatral, principalmente a brasileira.", "o": "• Contextos e práticas."}, {"a": "6", "t": "3", "c": "EF69AR26-06/ES", "e": "", "h": "Explorar diferentes elementos envolvidos na composição dos acontecimentos cênicos (figurinos, adereços, cenário, iluminação e sonoplastia) e reconhecer seus vocabulários, percebendo as características desses elementos na produção teatral brasileira de diferentes épocas.", "o": "• Elementos da linguagem."}, {"a": "6", "t": "3", "c": "EF69AR27-06/ES", "e": "", "h": "Pesquisar e criar formas de dramaturgia e espaços cênicos para o acontecimento teatral, em diálogo com o teatro contemporâneo, pesquisando nas salas de aula, na escola ou em ambiente externos a possibilidade de espaços físicos em espaços cênicos.", "o": "• Processos de criação"}, {"a": "6", "t": "3", "c": "EF69AR28-06/ES", "e": "", "h": "Investigar e experimentar diferentes funções teatrais e discutir os limites e desafios do trabalho artístico coletivo e colaborativo, experimentando a construção de roteiros/cenas que tenham: enredo, história, conflito dramático, personagens, diálogo local e ações dramáticas definidas.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR29-06/ES", "e": "", "h": "Experimentar a gestualidade e as construções corporais e vocais de maneira imaginativa na improvisação teatral e no jogo cênico, utilizando a capacidade de expressar e criar significados no plano sensório-corporal.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR30-06/ES", "e": "", "h": "Compor improvisações e acontecimentos cênicos com base em textos dramáticos ou outros estímulos (música, imagens, objetos etc.), caracterizando personagens (com figurinos e adereços), cenário, iluminação e sonoplastia e considerando a relação com o espectador.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR32-06/ES", "e": "", "h": "Analisar e explorar, em projetos temáticos, as relações processuais entre diversas linguagens artísticas, valorizando a identidade do povo brasileiro.", "o": "• Processos de criação."}, {"a": "7", "t": "1", "c": "EF69AR01-07/ES", "e": "", "h": "Pesquisar, apreciar e analisar formas distintas das artes visuais tradicionais e contemporâneas que se apresentem em espaços públicos e/ou arquitetônicos: espaços urbanos, paisagens naturais, ciberespaços, entre outros, em obras de artistas brasileiros e estrangeiros de diferentes épocas e em diferentes matrizes estéticas e culturais, de modo a ampliar a experiência com diferentes contextos e práticas artístico-visuais e cultivar a percepção, o imaginário, a capacidade de simbolizar e o repertório imagético.", "o": "• Contextos e práticas."}, {"a": "7", "t": "1", "c": "EF69AR02-07/ES", "e": "", "h": "Pesquisar e analisar diferentes estilos visuais, contextualizando-os no tempo e no espaço, comparando obras de artes de diferentes espaços públicos (nacionais e internacionais) com obras realizadas em espaços naturais em diversos lugares.", "o": "• Contextos e práticas."}, {"a": "7", "t": "1", "c": "EF69AR03-07/ES", "e": "", "h": "Analisar situações nas quais as linguagens das artes visuais se integram às linguagens audiovisuais (cinema, animações, vídeos etc.), gráficas (capas de livros, ilustrações de textos diversos etc.), cenográficas, coreográficas, musicais etc., principalmente em espaços públicos.", "o": "• Contextos e práticas."}, {"a": "7", "t": "1", "c": "EF69AR04-07/ES", "e": "", "h": "Analisar os elementos constitutivos das artes visuais (ponto, linha, forma, direção, cor, tom, escala, dimensão, espaço, movimento etc.) na apreciação de diferentes produções artísticas, considerando os conteúdos gerados a partir de suas articulações internas e contextuais.", "o": "• Elementos da linguagem."}, {"a": "7", "t": "1", "c": "EF69AR05-07/ES", "e": "", "h": "Experimentar e analisar diferentes formas de expressão artística (desenho, pintura, colagem, quadrinhos, dobradura, escultura, modelagem, instalação, vídeo, fotografia, performance etc.), percebendo as potencialidades e possibilidades de cada meio, materiais e instrumentos utilizados por diferentes artistas brasileiros.", "o": "• Materialidades."}, {"a": "7", "t": "1", "c": "EF69AR06-07/ES", "e": "", "h": "Desenvolver processos de criação em artes visuais, com base em temas ou interesses artísticos, potencializando a criação em arte como ocupação de diferentes espaços, de modo individual, coletivo e colaborativo, fazendo uso de materiais, instrumentos e recursos convencionais, alternativos e digitais.", "o": "• Processos de criação."}, {"a": "7", "t": "1", "c": "EF69AR07-07/ES", "e": "", "h": "Dialogar com princípios conceituais, proposições temáticas, repertórios imagéticos e processos de criação nas suas produções visuais, aprofundando a poética pessoal e ampliando o vocabulário próprio.", "o": "• Processos de criação."}, {"a": "7", "t": "1", "c": "EF69AR08-07/ES", "e": "", "h": "Diferenciar as categorias de artista, artesão, produtor cultural, curador, designer, entre outras, estabelecendo relações entre os profissionais do sistema das artes visuais, conhecendo a função de cada um desses agentes na elaboração de saraus, exposições, eventos culturais, etc.", "o": "• Sistemas da linguagem."}, {"a": "7", "t": "1", "c": "EF69AR31-07/ES", "e": "", "h": "Relacionar as práticas artísticas às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética, a partir de uma situação local ou da região e da experiência com o teatro de espaços não convencionais, possibilitando observação ou pesquisa presencial, exercitando a escuta e a construção de um olhar preceptivo.", "o": "• Contextos e práticas."}, {"a": "7", "t": "1", "c": "EF69AR33-07/ES", "e": "", "h": "Analisar aspectos históricos, sociais e políticos da produção artística, problematizando as narrativas eurocêntricas e as diversas categorizações da arte (arte, artesanato, folclore, design etc.), identificando das diferentes matrizes estéticas nas produções de arte públicas.", "o": "• Matrizes estéticas e culturais."}, {"a": "7", "t": "1", "c": "EF69AR34-07/ES", "e": "", "h": "Analisar e valorizar o patrimônio cultural, material e imaterial, de culturas diversas, em especial a brasileira, incluindo suas matrizes indígenas, africanas e europeias, de diferentes épocas, e favorecendo a construção de vocabulário e repertório relativos às diferentes linguagens artísticas, relacionando a arte pública à educação patrimonial.", "o": "• Patrimônio cultural."}, {"a": "7", "t": "1", "c": "EF69AR35-07/ES", "e": "", "h": "Identificar e manipular diferentes tecnologias e recursos digitais para acessar, apreciar, produzir, registrar e compartilhar práticas e repertórios artísticos, de modo reflexivo, ético e responsável, permeando os espaços públicos de diferentes contextos.", "o": "• Arte e tecnologia."}, {"a": "7", "t": "2", "c": "EF69AR09-07/ES", "e": "", "h": "Pesquisar e analisar diferentes formas de expressão, representação e encenação da dança, reconhecendo e apreciando composições de dança de artistas e grupos brasileiros e estrangeiros, de diferentes épocas, que se apresentam em diferentes espaços públicos: praças, ruas, escolas, igrejas, tribos, terreiros, etc.", "o": "• Contextos e práticas."}, {"a": "7", "t": "2", "c": "EF69AR10-07/ES", "e": "", "h": "Explorar elementos constitutivos do movimento cotidiano e do movimento dançado, abordando, criticamente, o desenvolvimento das formas da dança, em sua história tradicional e contemporânea, percebendo os significados desses elementos nas danças em espaços públicos.", "o": "• Elementos da linguagem."}, {"a": "7", "t": "2", "c": "EF69AR16-07/ES", "e": "", "h": "Analisar criticamente, por meio da apreciação musical, usos e funções da música em seus contextos de produção e circulação, observando as manifestações musicais que acontecem em diferentes espaços públicos: carnaval, festivais, festas urbanas, festas tradicionais etc., relacionando as práticas musicais às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética.", "o": "• Contextos e práticas."}, {"a": "7", "t": "2", "c": "EF69AR17-07/ES", "e": "", "h": "Explorar e analisar, criticamente, diferentes meios e equipamentos culturais de circulação da música e do conhecimento musical, ampliando a concepção de espaço de criação e apresentação musical e reconhecendo as ruas, praças e demais espaços coletivos como potencialidades.", "o": "• Contextos e práticas."}, {"a": "7", "t": "2", "c": "EF69AR18-07/ES", "e": "", "h": "Reconhecer e apreciar o papel de músicos e grupos de música brasileiros e estrangeiros que contribuíram para o desenvolvimento de formas e gêneros musicais presentes nas ruas das cidades e nos espaços do campo do interior do país.", "o": "• Contextos e práticas."}, {"a": "7", "t": "2", "c": "EF69AR19-07/ES", "e": "", "h": "Identificar e analisar diferentes estilos musicais, contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética musical, percebendo os estilos que se popularizaram entre as massas e que estão presentes nos grandes festivais de música, analisando seus impactos nos processos de construção ética e cultural.", "o": "•Contextos e práticas."}, {"a": "7", "t": "2", "c": "EF69AR20-07/ES", "e": "", "h": "Explorar e analisar elementos constitutivos da música (altura, intensidade, timbre, melodia, ritmo etc.), por meio de recursos tecnológicos (games e plataformas digitais), jogos, canções e práticas diversas de composição/criação, execução e apreciação musicais presentes nos diversos espaços do território nacional.", "o": "• Elementos da linguagem."}, {"a": "7", "t": "2", "c": "EF69AR21", "e": "", "h": "Explorar e analisar fontes e materiais sonoros em práticas de composição/criação, execução e apreciação musical, reconhecendo timbres e características de instrumentos musicais diversos.", "o": "• Materialidades."}, {"a": "7", "t": "2", "c": "EF69AR22-07/ES", "e": "", "h": "Explorar e identificar diferentes formas de registro musical não convencional (como partituras criativas e procedimentos da música contemporânea brasileira), bem como procedimentos e técnicas de registro em áudio e audiovisual e reconhecer princípios da notação musical convencional.", "o": "• Notação e registro musical."}, {"a": "7", "t": "2", "c": "EF69AR23-07/ES", "e": "", "h": "Explorar e criar improvisações, composições, arranjos, jingles, trilhas sonoras, entre outros, utilizando vozes, sons corporais e/ou instrumentos acústicos ou eletrônicos, convencionais ou não convencionais, expressando ideias musicais de maneira individual, coletiva e colaborativa, além de relacionar as experiências propostas com a apreciação de diferentes músicos ou músicas apresentados em espaços públicos.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR11-07/ES", "e": "", "h": "Experimentar e analisar os fatores de movimento (tempo, peso, fluência e espaço) como elementos que, combinados, geram as ações corporais e o movimento dançado, ampliando o seu próprio repertório.", "o": "• Elementos da linguagem."}, {"a": "7", "t": "3", "c": "EF69AR12-07/ES", "e": "", "h": "Investigar e experimentar procedimentos de improvisação e criação do movimento como fonte para a construção de vocabulários e repertórios próprios.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR13-07/ES", "e": "", "h": "Investigar brincadeiras, jogos, danças coletivas e outras práticas de dança de diferentes matrizes estéticas e culturais como referência para a criação e a composição de danças autorais, individualmente e em grupo, procurando interagir com diferentes espaços públicos.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR14-07/ES", "e": "", "h": "Analisar e experimentar diferentes elementos (figurino, iluminação, cenário, trilha sonora etc.) e espaços (convencionais e não convencionais) para composição cênica e apresentação coreográfica em diferentes espaços públicos.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR15-07/ES", "e": "", "h": "Discutir as experiências pessoais e coletivas em dança vivenciadas na escola e em outros contextos, problematizando estereótipos e preconceitos, principalmente aqueles vinculados às danças de comunidades marginalizadas.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR24-07/ES", "e": "", "h": "Reconhecer e apreciar artistas e grupos de teatro brasileiros e estrangeiros de diferentes épocas, investigando os modos de criação, produção, divulgação, circulação e organização da atuação profissional em teatro, dando ênfase na produção de teatro realizada em espaços exteriores às construções tradicionais, como nas ruas, praças, mercados, metrôs, universidades e outros.", "o": "• Contextos e práticas."}, {"a": "7", "t": "3", "c": "EF69AR25-07/ES", "e": "", "h": "Identificar e analisar diferentes estilos cênicos (realista, tragédia clássica, tragédia moderna, comédia clássica, comédia moderna, teatro contemporâneo, teatro de rua, teatro de bonecos, circo, entre outros), a fim de ampliar o repertório, contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética teatral.", "o": "• Contextos e práticas."}, {"a": "7", "t": "3", "c": "EF69AR26-07/ES", "e": "", "h": "Explorar diferentes elementos envolvidos na composição dos acontecimentos cênicos (figurinos, adereços, cenário, iluminação e sonoplastia) e reconhecer seus vocabulários, percebendo as características desses elementos na produção teatral presente em diferentes territorialidades.", "o": "• Elementos da linguagem."}, {"a": "7", "t": "3", "c": "EF69AR27-07/ES", "e": "", "h": "Pesquisar e criar formas de dramaturgias e espaços cênicos para o acontecimento teatral, em diálogo com o teatro contemporâneo, pesquisando, nos espaços da escola e em ambientes externos, a possibilidade de uso dos espaços físicos como espaços cênicos.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR28-07/ES", "e": "", "h": "Investigar e experimentar diferentes funções teatrais e discutir os limites e desafios do trabalho artístico de coletivos teatrais, de forma coletiva e colaborativa, experimentando a construção de roteiros/cenas que tenham: enredo/história/ conflito dramático/ personagens/ diálogo local e ação dramática definida.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR29-07/ES", "e": "", "h": "Experimentar a gestualidade e as construções corporais e vocais de maneira imaginativa na improvisação teatral e no jogo cênico, utilizando a capacidade de expressar e criar significados no plano sensório-corporal.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR30-07/ES", "e": "", "h": "Compor improvisações e acontecimentos cênicos com base em textos dramáticos ou outros estímulos (música, imagens, objetos etc.), caracterizando personagens (com figurinos e adereços), cenário, iluminação e sonoplastia e considerando a relação com o espectador.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR32-07/ES", "e": "", "h": "Analisar e explorar, em projetos temáticos, as relações processuais entre diversas linguagens artísticas, valorizando a produção de arte em espaços públicos.", "o": "• Processos de criação."}, {"a": "8", "t": "1", "c": "EF69AR01-08/ES", "e": "", "h": "Pesquisar, apreciar e analisar formas distintas das artes visuais tradicionais e contemporâneas, em que se identifiquem as lutas ideológicas, sociais e políticas, em obras de artistas brasileiros e estrangeiros de diferentes épocas e em diferentes matrizes estéticas e culturais, de modo a ampliar a experiência com diversos contextos e práticas artístico-visuais e cultivar a percepção, o imaginário, a capacidade de simbolizar e o repertório imagético, possibilitando sua compreensão e ressignificação.", "o": "• Contextos e práticas."}, {"a": "8", "t": "1", "c": "EF69AR02-08/ES", "e": "", "h": "Pesquisar e analisar diferentes estilos visuais que produziram uma arte de reflexão e contestação, contextualizando-os no tempo e no espaço, compreendendo os momentos históricos e socioculturais ao longo das diferentes histórias das artes.", "o": "• Contextos e práticas."}, {"a": "8", "t": "1", "c": "EF69AR03-08/ES", "e": "", "h": "Analisar situações nas quais as linguagens das artes visuais se integram às linguagens audiovisuais (cinema, animações, vídeos etc.), gráficas (capas de livros, ilustrações de textos diversos etc.), cenográficas, coreográficas, musicais etc., pesquisando, principalmente nas obras de arte de cunho social, político, ecológico e ideológico.", "o": "• Contextos e práticas."}, {"a": "8", "t": "1", "c": "EF69AR04-08/ES", "e": "", "h": "Analisar os elementos constitutivos das artes visuais (ponto, linha, forma, direção, cor, tom, escala, dimensão, espaço, movimento etc.) na apreciação de diferentes produções artísticas, identificando-os conforme o material e o meio em que a obra é realizada, além de refletir sobre as relações dos elementos visuais, tanto internas quanto contextuais.", "o": "• Elementos da linguagem."}, {"a": "8", "t": "1", "c": "EF69AR05-08/ES", "e": "", "h": "Experimentar e analisar diferentes formas de expressão artística (desenho, pintura, colagem, quadrinhos, dobradura, escultura, modelagem, instalação, vídeo, fotografia, performance, etc.), percebendo as possibilidades criativas de cada suporte, meio, instrumento e materiais utilizados nas obras.", "o": "• Materialidades."}, {"a": "8", "t": "1", "c": "EF69AR06-08/ES", "e": "", "h": "Desenvolver processos de criação em artes visuais, com base em temas ou interesses artísticos, de modo individual, coletivo e colaborativo, fazendo uso de materiais, instrumentos e recursos convencionais, alternativos e digitais, aprimorando seu pensamento criativo em arte.", "o": "• Processos de criação."}, {"a": "8", "t": "1", "c": "EF69AR07-08/ES", "e": "", "h": "Dialogar com princípios conceituais, proposições temáticas, repertórios imagéticos e processos de criação, nas suas produções visuais, estabelecendo relações com o repertório do aluno.", "o": "• Processos de criação."}, {"a": "8", "t": "1", "c": "EF69AR08-08/ES", "e": "", "h": "Diferenciar as categorias de artista, artesão, produtor cultural, curador, designer, entre outras, ampliando a compreensão das categorias e estabelecendo relações entre os profissionais do sistema das artes visuais.", "o": "• Sistemas da linguagem."}, {"a": "8", "t": "1", "c": "EF69AR31-08/ES", "e": "", "h": "Relacionar as práticas artísticas às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética, possibilitando a escuta e a construção de um olhar perceptivo, apreendendo a arte como instrumento de expressão e de comunicação de ideias políticas, sociais e ambientais.", "o": "• Contextos e práticas."}, {"a": "8", "t": "1", "c": "EF69AR33-08/ES", "e": "", "h": "Analisar aspectos históricos, sociais e políticos da produção artística, problematizando as narrativas eurocêntricas e as diversas categorizações da arte (arte, artesanato, folclore, design etc.), percebendo a arte como ferramenta de fortalecimento de diferentes etnias.", "o": "• Matrizes estéticas e culturais."}, {"a": "8", "t": "1", "c": "EF69AR34-08/ES", "e": "", "h": "Analisar e valorizar o patrimônio cultural, material e imaterial, de culturas diversas, em especial a brasileira, incluindo suas matrizes indígenas, africanas e europeias, de diferentes épocas, e favorecendo a construção de vocabulário e repertório relativos às diversas linguagens artísticas, participando da identificação do que constitui o patrimônio material (arquitetura), imaterial, histórico, artístico e natural.", "o": "• Patrimônio Cultural."}, {"a": "8", "t": "1", "c": "EF69AR35-08/ES", "e": "", "h": "Identificar e manipular diferentes tecnologias e recursos digitais para acessar, apreciar, produzir, registrar e compartilhar práticas e repertórios artísticos, de modo reflexivo, ético e responsável, dialogando com a arte de reflexão.", "o": "• Arte e tecnologia."}, {"a": "8", "t": "2", "c": "EF69AR09-08/ES", "e": "", "h": "Pesquisar e analisar diferentes formas de expressão, representação e encenação da dança que articulam um pensamento crítico e reflexivo, reconhecendo e apreciando composições de dança de artistas e grupos brasileiros e estrangeiros de diferentes épocas.", "o": "• Contextos e práticas."}, {"a": "8", "t": "2", "c": "EF69AR10-08/ES", "e": "", "h": "Explorar elementos constitutivos do movimento cotidiano e do movimento dançado, abordando, criticamente, o desenvolvimento das formas da dança em sua história tradicional e contemporânea, reconhecendo a potencialidade expressiva do gesto e do movimento cotidiano para transformar-se em dança.", "o": "• Elementos da linguagem."}, {"a": "8", "t": "2", "c": "EF69AR16-08/ES", "e": "", "h": "Analisar criticamente, por meio da apreciação musical, usos e funções da música em seus contextos de produção e circulação, relacionando as práticas musicais às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética, destacando o caráter crítico, político e social de diferentes músicas e gêneros musicais.", "o": "• Contextos e práticas."}, {"a": "8", "t": "2", "c": "EF69AR17-08/ES", "e": "", "h": "Explorar e analisar, criticamente, diferentes meios e equipamentos culturais de circulação da música e do conhecimento musical, ampliando e/ou desenvolvendo uma escuta crítica da música.", "o": "• Contextos e práticas."}, {"a": "8", "t": "2", "c": "EF69AR18-08/ES", "e": "", "h": "Reconhecer e apreciar o papel de músicos e grupos de música brasileiros e estrangeiros que contribuíram para o desenvolvimento de formas e gêneros musicais, em especial músicos e bandas de ativismos políticos, ideológicos e sociais.", "o": "• Contextos e práticas."}, {"a": "8", "t": "2", "c": "EF69AR19-08/ES", "e": "", "h": "Identificar e analisar diferentes estilos musicais, contextualizando-os no tempo e no espaço, de modo a aprimorar e ampliar a capacidade de apreciação da estética musical.", "o": "• Contextos e práticas."}, {"a": "8", "t": "2", "c": "EF69AR20-08/ES", "e": "", "h": "Explorar e analisar elementos constitutivos da música (altura, intensidade, timbre, melodia, ritmo etc.), por meio de recursos tecnológicos (games e plataformas digitais), jogos, canções e práticas diversas de composição/ criação, execução e apreciação musicais, ampliando a percepção dos parâmetros do som e os elementos básicos da música.", "o": "• Elementos da linguagem."}, {"a": "8", "t": "2", "c": "EF69AR21-08/ES", "e": "", "h": "Explorar e analisar fontes e materiais sonoros locais e regionais em práticas de composição/criação, execução e apreciação musical, reconhecendo timbres e características de instrumentos musicais diversos.", "o": "• Materialidades."}, {"a": "8", "t": "2", "c": "EF69AR22-08/ES", "e": "", "h": "Explorar e identificar diferentes formas de registro musical não convencional (como partituras criativas e procedimentos da música contemporânea brasileira), bem como procedimentos e técnicas de registro em áudio e audiovisual e reconhecer princípios da notação musical convencional.", "o": "• Notação e registro musical."}, {"a": "8", "t": "2", "c": "EF69AR23-08/ES", "e": "", "h": "Explorar e criar improvisações, composições, arranjos, jingles, trilhas sonoras, entre outros, utilizando vozes, sons corporais e/ou instrumentos acústicos ou eletrônicos, convencionais ou não convencionais, expressando ideias musicais de maneira individual, coletiva e colaborativa, relacionando as experiências propostas com a apreciação de diferentes músicos ou músicas, locais, nacionais e internacionais.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR11-08/ES", "e": "", "h": "Experimentar e analisar os fatores de movimento (tempo, peso, fluência e espaço) como elementos que, combinados, geram as ações corporais e o movimento dançado, ampliando o seu próprio repertório.", "o": "• Elementos da linguagem."}, {"a": "8", "t": "3", "c": "EF69AR12-08/ES", "e": "", "h": "Investigar e experimentar procedimentos de improvisação e criação do movimento como fonte para a construção de vocabulários e repertórios próprios, inspirados ou não em manifestações de dança.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR13-08/ES", "e": "", "h": "Investigar e experimentar brincadeiras, jogos, danças coletivas e outras práticas de dança de diferentes matrizes estéticas e culturais como referência para a criação e a composição de danças autorais, individualmente e em grupo.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR14", "e": "", "h": "Analisar e experimentar diferentes elementos (figurino, iluminação, cenário, trilha sonora etc.) e espaços (convencionais e não convencionais) para composição cênica e apresentação coreográfica.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR15-08/ES", "e": "", "h": "Discutir as experiências pessoais e coletivas em dança vivenciadas na escola e em outros contextos, problematizando estereótipos e preconceitos.", "o": "•Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR24-08/ES", "e": "", "h": "Reconhecer e apreciar artistas e grupos de teatro brasileiros e estrangeiros de diferentes épocas, investigando os modos de criação, produção, divulgação, circulação e organização da atuação profissional em teatro e identificando as diferentes visões socioculturais, antropológicas e políticas no Teatro.", "o": "• Contextos e práticas."}, {"a": "8", "t": "3", "c": "EF69AR25-08/ES", "e": "", "h": "Identificar e analisar diferentes estilos cênicos (melodrama, teatro de revista, peças didáticas, entre outros), contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética teatral.", "o": "• Contextos e práticas."}, {"a": "8", "t": "3", "c": "EF69AR26-08/ES", "e": "", "h": "Explorar diferentes elementos (figurinos, adereços, cenário, iluminação e sonoplastia) envolvidos na composição dos acontecimentos cênicos e reconhecer seus vocabulários.", "o": "• Elementos da linguagem."}, {"a": "8", "t": "3", "c": "EF69AR27-08/ES", "e": "", "h": "Pesquisar e criar formas de dramaturgia e espaços cênicos para o acontecimento teatral, em diálogo com o teatro contemporâneo, pesquisando nos espaços da escola e em ambientes externos a possibilidade de uso dos espaços físicos como espaços cênicos.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR28-08/ES", "e": "", "h": "Investigar e experimentar diferentes funções teatrais, além de discutir, de forma coletiva e colaborativa, os limites e desafios do trabalho artístico de coletivos teatrais, experimentando a construção de roteiros/ cenas que tenham: enredo/ história/ conflito dramático/ personagens/ diálogo local e ação dramática definida.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR29-08/ES", "e": "", "h": "Experimentar a gestualidade e as construções corporais e vocais, de maneira imaginativa, na improvisação teatral e no jogo cênico, utilizando a capacidade de expressar e criar significados no plano sensório-corporal.", "o": "•Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR30-08/ES", "e": "Teatro.", "h": "Compor improvisações e acontecimentos cênicos com base em textos dramáticos ou outros estímulos (música, imagens, objetos etc.), caracterizando personagens (com figurinos e adereços), cenário, iluminação e sonoplastia e considerando a relação com o espectador.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR32-08/ES", "e": "Artes integradas.", "h": "Analisar e explorar, em projetos temáticos, as relações processuais entre diversas linguagens artísticas, utilizandose da arte como instrumento de transformação política e social.", "o": "• Processos de criação."}, {"a": "9", "t": "1", "c": "EF69AR01-09/ES", "e": "", "h": "Pesquisar, apreciar e analisar formas distintas das artes visuais tradicionais e contemporâneas, a partir de manifestações artísticas com o uso de computadores, criações multimídias, fotografia, vídeo e som, em obras de artistas brasileiros e estrangeiros de diferentes épocas e em diferentes matrizes estéticas e culturais, de modo a ampliar a experiência com diversificados contextos e práticas artístico-visuais e cultivar a percepção, o imaginário, a capacidade de simbolizar e o repertório imagético.", "o": "•Contextos e práticas."}, {"a": "9", "t": "1", "c": "EF69AR02-09/ES", "e": "", "h": "Pesquisar e analisar diferentes estilos visuais relacionados às mídias digitais: conteúdos, temas, histórias e interfaces com as mídias tradicionais, contextualizando-os no tempo e no espaço.", "o": "• Contextos e práticas."}, {"a": "9", "t": "1", "c": "EF69AR03-09/ES", "e": "", "h": "Analisar situações nas quais as linguagens das artes visuais se integram às linguagens audiovisuais (cinema, animações, vídeos etc.), gráficas (capas de livros, ilustrações de textos diversos etc.), cenográficas, coreográficas, musicais etc, pesquisando sobre as novas relações entre arte, tecnologia e ciências.", "o": "• Contextos e práticas."}, {"a": "9", "t": "1", "c": "EF69AR04-09/ES", "e": "", "h": "Analisar os elementos constitutivos das artes visuais (ponto, linha, forma, direção, cor, tom, escala, dimensão, espaço, movimento etc.) na apreciação de diferentes produções artísticas, considerando os conteúdos gerados a partir de suas articulações internas e contextuais.", "o": "• Elementos da linguagem."}, {"a": "9", "t": "1", "c": "EF69AR05-09/ES", "e": "", "h": "Experimentar e analisar diferentes formas de expressão artística (desenho, pintura, colagem, quadrinhos, dobradura, escultura, modelagem, instalação, vídeo, fotografia, performance etc.), incorporando equipamentos multimídia, ambientes imersivos e códigos de programação.", "o": "• Materialidades."}, {"a": "9", "t": "1", "c": "EF69AR06-09/ES", "e": "", "h": "Desenvolver processos de criação em artes visuais, com base em temas ou interesses artísticos, de modo individual, coletivo e colaborativo, fazendo uso de materiais, instrumentos e recursos convencionais, alternativos e digitais, expandido a criação com as mídias digitais.", "o": "• Processos de criação."}, {"a": "9", "t": "1", "c": "EF69AR07-09/ES", "e": "", "h": "Dialogar com princípios conceituais, proposições temáticas, repertórios imagéticos e processos de criação nas suas produções visuais, experimentando obras de arte com abrangência multissensorial (obras interativas e ambientes imersivos).", "o": "• Processos de criação."}, {"a": "9", "t": "1", "c": "EF69AR08-09/ES", "e": "", "h": "Diferenciar as categorias de artista, artesão, produtor cultural, curador, designer, entre outras, estabelecendo relações entre os profissionais do sistema das artes visuais, com a observação do designer como criação em novas tecnologias.", "o": "• Sistemas de linguagem."}, {"a": "9", "t": "1", "c": "EF69AR31-09/ES", "e": "", "h": "Relacionar as práticas artísticas tecnológicas às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética.", "o": "• Contextos e práticas."}, {"a": "9", "t": "1", "c": "EF69AR33-09/ES", "e": "", "h": "Analisar aspectos históricos, sociais e políticos que influenciaram as diversas produções artísticas, problematizando as narrativas eurocêntricas, reconhecendo diferentes áreas culturais e intentando não mostrar um passado somente eurocêntrico, mas as diversas categorizações da arte (arte, artesanato, folclore, design etc.).", "o": "• Matrizes estéticas e culturais."}, {"a": "9", "t": "1", "c": "EF69AR34-09/ES", "e": "", "h": "Analisar e valorizar o patrimônio cultural, material (bens históricos, paisagísticos, etnográficos, obras de arte, entre outros) e imaterial (os saberes, habilidades, crenças, celebrações, manifestações, entre outros), de culturas diversas, em especial a brasileira, incluindo suas matrizes indígenas, africanas e europeias, de diferentes épocas, e favorecendo a construção de vocabulário e repertório relativos às diferentes linguagens artísticas.", "o": "• Patrimônio cultural."}, {"a": "9", "t": "1", "c": "EF69AR35-09/ES", "e": "", "h": "Identificar e manipular diferentes tecnologias e recursos digitais para acessar, apreciar, produzir, registrar e compartilhar práticas e repertórios artísticos, de modo reflexivo, ético e responsável.", "o": "• Arte e tecnologia."}, {"a": "9", "t": "2", "c": "EF69AR09-09/ES", "e": "", "h": "Pesquisar e analisar diferentes formas de expressão, representação e encenação da dança que estabeleçam a relação entre arte e tecnologia, reconhecendo e apreciando composições de dança de artistas e grupos brasileiros e estrangeiros de diferentes épocas.", "o": "• Contextos e práticas."}, {"a": "9", "t": "2", "c": "EF69AR10-09/ES", "e": "", "h": "Explorar elementos constitutivos do movimento cotidiano e do movimento dançado, abordando, criticamente, o desenvolvimento das formas da dança em sua história tradicional e contemporânea, com observação nos efeitos visuais, jogos de luz, efeitos sonoros e utilização de multimídias na dança.", "o": "• Elementos da linguagem"}, {"a": "9", "t": "2", "c": "EF69AR16-09/ES", "e": "", "h": "Analisar criticamente, por meio da apreciação musical, usos e funções da música em seus contextos de produção e circulação, incluindo as novas plataformas, dispositivos e aplicativos de produção e distribuição de música, relacionando as práticas musicais às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética.", "o": "• Contextos e práticas"}, {"a": "9", "t": "2", "c": "EF69AR17-09/ES", "e": "", "h": "Explorar e analisar, criticamente, diferentes meios e equipamentos culturais de circulação da música e do conhecimento musical, percebendo a relação da música com a tecnologia.", "o": "• Contextos e práticas."}, {"a": "9", "t": "2", "c": "EF69AR18-09/ES", "e": "", "h": "Reconhecer e apreciar o papel de músicos e grupos de música brasileiros e estrangeiros que contribuíram para o desenvolvimento de formas e gêneros musicais, incluindo manifestações musicais contemporâneas produzidas a partir de novas tecnologias (música eletrônica, música eletroacústica e músicas produzidas a partir de aplicativos e dispositivos eletrônicos).", "o": "• Contextos e práticas"}, {"a": "9", "t": "2", "c": "EF69AR19-09/ES", "e": "", "h": "Identificar e analisar diferentes estilos musicais, incluindo as músicas produzidas através de novas tecnologias, contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética musical contemporânea.", "o": "• Contextos e práticas."}, {"a": "9", "t": "2", "c": "EF69AR20-09/ES", "e": "", "h": "Explorar e analisar elementos constitutivos da música (altura, intensidade, timbre, melodia, ritmo etc.), por meio de recursos tecnológicos (games e plataformas digitais), jogos, canções e práticas diversas de composição/ criação, execução e apreciação musicais, ampliando a percepção dos parâmetros do som e os elementos básicos da música.", "o": "• Elementos de linguagem."}, {"a": "9", "t": "2", "c": "EF69AR21-09/ES", "e": "", "h": "Explorar e analisar fontes e materiais sonoros em práticas de composição/criação, execução e apreciação musical, reconhecendo timbres e características de instrumentos musicais diversos: acústicos, elétricos e eletrônicos.", "o": "•Materialidades."}, {"a": "9", "t": "2", "c": "EF69AR22", "e": "", "h": "Explorar e identificar diferentes formas de registro musical (notação musical tradicional, partituras criativas e procedimentos da música contemporânea), bem como procedimentos e técnicas de registro em áudio e audiovisual.", "o": "• Notação e registro musical."}, {"a": "9", "t": "2", "c": "EF69AR23-09/ES", "e": "", "h": "Explorar e criar improvisações, composições, arranjos, jingles, trilhas sonoras, entre outros, utilizando vozes, sons corporais e/ou instrumentos acústicos ou eletrônicos, convencionais ou não convencionais, expressando ideias musicais de maneira individual, coletiva e colaborativa.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR11-09/ES", "e": "", "h": "Experimentar e analisar os fatores de movimento (tempo, peso, fluência e espaço) como elementos que, combinados, geram as ações corporais e o movimento dançado, ampliando o seu próprio repertório.", "o": "• Elementos da linguagem."}, {"a": "9", "t": "3", "c": "EF69AR12-09/ES", "e": "", "h": "Investigar e experimentar procedimentos de improvisação e criação do movimento, em performance e instalação, como fonte para a construção de vocabulários e repertórios próprios.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR13-09/ES", "e": "", "h": "Investigar brincadeiras, jogos, danças coletivas e outras práticas de dança de diferentes matrizes estéticas e culturais como referência para a criação e a composição de danças autorais, individualmente e em grupo, utilizando de mídias digitais e outras tecnologias.", "o": "• Processos de criação"}, {"a": "9", "t": "3", "c": "EF69AR14-09/ES", "e": "", "h": "Analisar e experimentar diferentes elementos (figurino, iluminação, cenário, trilha sonora etc.) e espaços (convencionais e não convencionais) para composição cênica e apresentação coreográfica, conhecendo a especificidade dos elementos na criação e produção artística da dança.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR15-09/ES", "e": "", "h": "Discutir as experiências pessoais e coletivas em dança vivenciadas na escola e em outros contextos, problematizando estereótipos e preconceitos.", "o": "• Processos de criação"}, {"a": "9", "t": "3", "c": "EF69AR24-09/ES", "e": "", "h": "Reconhecer e apreciar artistas e grupos de teatro brasileiros e estrangeiros de diferentes épocas, investigando os modos de criação, produção, divulgação, circulação e organização da atuação profissional em teatro, integrando linguagens, tecnologia e o público.", "o": "• Contextos e práticas."}, {"a": "9", "t": "3", "c": "EF69AR25-09/ES", "e": "", "h": "Identificar e analisar diferentes estilos cênicos, contextualizando-os no tempo e no espaço de modo a aprimorar a capacidade de apreciação da estética teatral. Ademais, ampliar a experiência de aprendizagem com a projeção de vídeos de espetáculos teatrais de diversas matrizes culturais.", "o": "• Contextos e práticas"}, {"a": "9", "t": "3", "c": "EF69AR26-09/ES", "e": "", "h": "Explorar diferentes elementos (figurinos, adereços, cenário, iluminação e sonoplastia) envolvidos na composição dos acontecimentos cênicos e reconhecer seus vocabulários.", "o": "• Elementos da linguagem."}, {"a": "9", "t": "3", "c": "EF69AR27-09/ES", "e": "", "h": "Pesquisar e criar formas de dramaturgia e espaços cênicos como possibilidades de transformação de um local físico para o acontecimento teatral, em diálogo com o teatro contemporâneo.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR28-09/ES", "e": "", "h": "Investigar e experimentar diferentes funções teatrais e discutir os limites e desafios do trabalho artístico coletivo e colaborativo, permitindo a compreensão dos modos coletivizados e de diretriz dialógica de fazerem teatro.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR29-09/ES", "e": "", "h": "Experimentar a gestualidade e as construções corporais e vocais de maneira imaginativa na improvisação teatral e no jogo cênico, potencializando a imaginação e narrativas para o exercício dessas expressividades.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR30-09/ES", "e": "", "h": "Compor e encenar improvisações e acontecimentos cênicos com base em textos dramáticos ou outros estímulos (música, imagens, objetos etc.), caracterizando personagens (com figurinos e adereços), cenário, iluminação e sonoplastia e considerando a relação com o espectador.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR32-09/ES", "e": "", "h": "Analisar e praticar, em projetos temáticos, as relações processuais entre diversas linguagens artísticas (teatro, dança, música e artes visuais).", "o": "• Processos de criação."}], "Educação Física": [{"a": "6", "t": "1", "c": "EF67EF03-06/ES", "e": "Esportes", "h": "Experimentar e fruir esportes de marca, precisão, invasão e técnico-combinatórios que façam parte do contexto social dos estudantes, valorizando o trabalho coletivo e o protagonismo, por meio de atividades lúdicas e criativas.", "o": "Esportes de Marca •Exemplos: Corridas, Saltos, Arremesso e Lançamentos do Atletismo; •Prática de habilidades específicas de esportes de marca, como técnica de corrida, saltos e arremessos, promovendo o desenvolvimento motor e a superação de desafios individuais e coletivos."}, {"a": "6", "t": "1", "c": "EF67EF04", "e": "Esportes", "h": "Praticar um ou mais esportes de marca, precisão, invasão e técnico-combinatórios oferecidos pela escola, usando habilidades técnico-táticas básicas e respeitando regras.", "o": "Esportes de Marca •Regras; •Fundamentos básicos (técnico-tático) dos esportes trabalhados; • Simulações de jogo para aplicar fundamentos técnicos e táticos, compreendendo as dinâmicas dos esportes de marca."}, {"a": "6", "t": "1", "c": "EF67EF05", "e": "Esportes", "h": "Planejar e utilizar estratégias para solucionar os desafios técnicos e táticos, tanto nos esportes de marca, precisão, invasão e técnico-combinatórios como nas modalidades esportivas escolhidas para praticar de forma específica.", "o": "Esportes de Marca •Análise das situações de jogo para identificar oportunidades e desafios, promovendo o desenvolvimento de soluções criativas e adaptativas nas práticas dos esportes de marca."}, {"a": "6", "t": "1", "c": "EF67EF06", "e": "Esportes", "h": "Analisar as transformações na organização e na prática dos esportes em suas diferentes manifestações (profissional e comunitário/lazer).", "o": "Esportes de Marca •Conceituação de prática profissional e prática amadora no esporte; •Análise das influências culturais e sociais na prática dos esportes de marca, incluindo o papel da mídia e da comunidade."}, {"a": "6", "t": "1", "c": "EF67EF07", "e": "Esportes", "h": "Propor e produzir alternativas para experimentação dos esportes não disponíveis e/ou acessíveis na comunidade e das demais práticas corporais tematizadas na escola.", "o": "Esportes de Marca •Adaptação de jogos e atividades esportivas com materiais acessíveis, promovendo inclusão e experimentação."}, {"a": "6", "t": "1", "c": "EF67EF08/ES", "e": "", "h": "Experimentar e fruir exercícios físicos que solicitem diferentes capacidades físicas, identificando seus tipos (força, velocidade, resistência, flexibilidade) e as sensações corporais provocadas pela sua prática, evidenciando a importância do aprimoramento das capacidades físicas para realizar tarefas em situações do cotidiano.", "o": "Ginástica de condicionamento físico • Capacidades físicas voltadas para a promoção da saúde e aprimoramento funcional; • Desenvolvimento das capacidades físicas para a realização eficiente de tarefas diárias, promovendo autonomia e bem-estar; • Atividades relacionadas às capacidades físicas abordadas, além das respostas corporais que eles provocam (ex.: suor, alteração da frequência cardíaca, alteração da temperatura corporal etc.)."}, {"a": "6", "t": "1", "c": "EF67EF09-06/ES", "e": "", "h": "Construir, coletivamente, procedimentos e normas de convívio que viabilizem a participação de todos na prática de exercícios físicos, com o objetivo de promover a saúde. Enfatizando processos que levem os estudantes a compreenderem a relação entre o exercício físico e a saúde, identificando as principais capacidades físicas e estruturas corporais envolvidas nesse processo.", "o": "Ginástica de condicionamento físico •Adaptação de exercícios para respeitar as limitações individuais, garantindo a participação de todos e promovendo a saúde."}, {"a": "6", "t": "1", "c": "EF67EF10", "e": "Ginásticas", "h": "Diferenciar exercício físico de atividade física e propor alternativas para a prática de exercícios físicos dentro e fora do ambiente escolar.", "o": "Ginástica de condicionamento físico •Diferenciação entre Atividade Física e Exercício Físico; •Exploração de formas acessíveis e criativas de realizar exercícios físicos no cotidiano, considerando os recursos disponíveis dentro e fora do ambiente escolar."}, {"a": "6", "t": "2", "c": "EF67EF14", "e": "Lutas", "h": "Experimentar, fruir e recriar diferentes lutas do Brasil, valorizando a própria segurança e integridade física, bem como as dos demais.", "o": "Lutas do Brasil •Tarracá, Jiu-Jitsu Brasileiro, Capoeira, Maculelê, Luta Marajoara, entre outras; •Cuidados e segurança durante a execução das lutas; •Modalidades (curta, média e longa distância)."}, {"a": "6", "t": "2", "c": "EF67EF15", "e": "Lutas", "h": "Planejar e utilizar estratégias básicas das lutas do Brasil, respeitando o colega como oponente.", "o": "Lutas do Brasil •Desenvolvimento da leitura de movimento e antecipação para identificar oportunidades nas lutas, priorizando o respeito e a segurança do colega."}, {"a": "6", "t": "2", "c": "EF67EF16", "e": "Lutas", "h": "Identificar as características (códigos, rituais, elementos técnico-táticos, indumentária, materiais, instalações, instituições) das lutas do Brasil.", "o": "Lutas do Brasil •Elementos constitutivos das lutas do Brasil (códigos, rituais, elementos técnico-táticos, indumentária, materiais, instalações, instituições); •Análise da diversidade regional das lutas do Brasil, destacando como as influências culturais locais moldam as práticas, os rituais e os estilos de luta."}, {"a": "6", "t": "2", "c": "EF67EF17", "e": "Lutas", "h": "Problematizar preconceitos e estereótipos relacionados ao universo das lutas e demais práticas corporais, propondo alternativas para superá-los, com base na solidariedade, na justiça, na equidade e no respeito.", "o": "Lutas do Brasil •Origem e herança cultural; •Racismo e exclusão social atrelados às lutas; •Comportamentos preconceituosos/ injustos relacionados às lutas brasileiras; •Problematização das lutas como atividade ligada ao universo masculino"}, {"a": "6", "t": "3", "c": "EF67EF01/ES", "e": "Brincadeiras e jogos", "h": "Experimentar e fruir, na escola e fora dela, jogos eletrônicos diversos atrelados as práticas corporais e de diferentes gêneros, valorizando e respeitando os sentidos e significados atribuídos a eles por diferentes grupos sociais e etários.", "o": "Jogos eletrônicos •Jogos eletrônicos individuais e de interação coletiva com ênfase nos que envolvam o corpo em movimento; •Análise dos aspectos culturais e sociais dos jogos eletrônicos, promovendo respeito e inclusão entre diferentes gêneros e grupos etários."}, {"a": "6", "t": "3", "c": "EF67EF02", "e": "Brincadeiras e jogos", "h": "Identificar as transformações nas características dos jogos eletrônicos em função dos avanços das tecnologias e nas respectivas exigências corporais colocadas por esses diferentes tipos de jogos.", "o": "Jogos eletrônicos •Caracterização de diferentes tipos de jogos eletrônicos; •Influência dos jogos eletrônicos no sedentarismo; •Influência dos jogos eletrônicos na dependência tecnológica."}, {"a": "6", "t": "3", "c": "EF67EF11-06/ES", "e": "", "h": "Experimentar, fruir e recriar danças urbanas, identificando seus elementos constitutivos (ritmo, espaço, gestos), bem como capacidades físicas durante as práticas das danças, como a coordenação motora, o equilíbrio, a agilidade, a flexibilidade, entre outras. Promovendo aprendizagens sobre o percurso histórico das danças urbanas, partindo-se das suas modalidades originais. O estudo do elemento constituinte espaço possibilita interações com o componente curricular Geografia.", "o": "Danças urbanas •Hip Hop, Funk, Freestyle, Passinho e outros; •Elementos constitutivos da dança urbana (ritmo e expressão corporal; tempo, organização espacial e marcação musical)."}, {"a": "6", "t": "3", "c": "EF67EF12", "e": "Danças", "h": "Planejar e utilizar estratégias para aprender elementos constitutivos das danças urbanas.", "o": "Danças urbanas •Criação de sequências coreográficas que integrem os elementos das danças urbanas, promovendo a criatividade e a expressão individual."}, {"a": "6", "t": "3", "c": "EF67EF13/ES", "e": "", "h": "Diferenciar as danças urbanas das demais manifestações da dança, valorizando e respeitando os sentidos e significados atribuídos a eles por diferentes grupos sociais. Há, aqui, oportunidade de trabalho interdisciplinar com o componente curricular da Arte, no que se refere à investigação de diferentes tipos de dança.", "o": "Danças urbanas •Aspectos do contexto sociocultural (ritmos, passos básicos, expressão corporal, espaços, vestimentas) das danças urbanas e sua diferenciação das demais manifestações de dança; • Análise dos aspectos históricos e culturais que diferenciam as danças urbanas de outras formas de dança, ressaltando a valorização da diversidade cultural."}, {"a": "6", "t": "3", "c": "EF67EF18-06/ES", "e": "Práticas corporais de aventura", "h": "Experimentar e fruir diferentes práticas corporais de aventura urbanas, que sejam conhecidas ou praticadas pelos estudantes, valorizando a própria segurança e integridade física, bem como as dos demais.", "o": "Práticas corporais de aventura urbanas •Parkour, Rapel, Skate, Slackline e outros; •Cuidados/Riscos relacionados à prática; •Limites corporais e superação do receio da realização da prática de uma determina prática de aventura; •Adaptação de espaços para a prática."}, {"a": "6", "t": "3", "c": "EF67EF19", "e": "Práticas corporais de aventura", "h": "Identificar os riscos durante a realização de práticas corporais de aventura urbanas e planejar estratégias para sua superação.", "o": "Práticas corporais de aventura urbanas •Equipamentos de segurança necessários para a prática de cada modalidade; •Riscos envolvidos nas práticas corporais de aventura no meio urbano; •Importância da preparação física e mental, incluindo aquecimento, alongamento e técnicas de respiração, para minimizar riscos nas práticas de aventura urbanas."}, {"a": "6", "t": "3", "c": "EF67EF20/ES", "e": "Práticas corporais de aventura", "h": "Executar práticas corporais de aventura urbanas, que sejam conhecidas ou praticadas pelos estudantes, respeitando o patrimônio público e utilizando alternativas para a prática segura em diversos espaços.", "o": "Práticas corporais de aventura urbanas •Exploração de espaços urbanos adequados para atividades de aventura, enfatizando segurança, legalidade e respeito ao patrimônio público, promovendo consciência cidadã."}, {"a": "6", "t": "3", "c": "EF67EF21", "e": "Práticas corporais de aventura", "h": "Identificar a origem das práticas corporais de aventura e as possibilidades de recriá-las, reconhecendo as características (instrumentos, equipamentos de segurança, indumentária, organização) e seus tipos de práticas.", "o": "Práticas corporais de aventura urbanas •Definição e caracterização das práticas; •Análise das influências culturais e sociais que moldam as práticas de aventura, incluindo tradições locais e sua adaptação aos contextos urbanos; •Evolução tecnológica dos itens de segurança e equipamentos."}, {"a": "7", "t": "1", "c": "EF67EF03-07/ES", "e": "Esportes", "h": "Experimentar e fruir esportes de marca, precisão, invasão e técnico-combinatórios, por meio de modalidades menos familiares aos estudantes, valorizando o trabalho coletivo e o protagonismo.", "o": "Esportes de Invasão •Exemplos: Futebol, Futsal, Handebol, basquetebol, entre outros."}, {"a": "7", "t": "1", "c": "EF67EF05", "e": "Esportes", "h": "Planejar e utilizar estratégias para solucionar os desafios técnicos e táticos, tanto nos esportes de marca, precisão, invasão e técnicocombinatórios como nas modalidades esportivas escolhidas para praticar de forma específica.", "o": "Esportes de Invasão •Análise das situações de jogo para identificar oportunidades e desafios, promovendo o desenvolvimento de soluções criativas e adaptativas nas práticas dos esportes de invasão."}, {"a": "7", "t": "1", "c": "EF67EF06", "e": "Esportes", "h": "Analisar as transformações na organização e na prática dos esportes em suas diferentes manifestações (profissional e comunitário/lazer).", "o": "Esportes de Invasão •Conceituação de prática profissional e prática amadora no esporte; •Análise das influências culturais e sociais na prática dos esportes de invasão, incluindo o papel da mídia e da comunidade."}, {"a": "7", "t": "1", "c": "EF67EF07", "e": "Esportes.", "h": "Propor e produzir alternativas para experimentação dos esportes não disponíveis e/ou acessíveis na comunidade e das demais práticas corporais tematizadas na escola.", "o": "Esportes de Invasão •Adaptação de jogos e atividades esportivas com materiais acessíveis, promovendo inclusão e experimentação."}, {"a": "7", "t": "1", "c": "EF67EF08/ES", "e": "", "h": "Experimentar e fruir exercícios físicos que solicitem diferentes capacidades físicas, identificando seus tipos (força, velocidade, resistência, flexibilidade) e as sensações corporais provocadas pela sua prática, evidenciando a importância do aprimoramento das capacidades físicas para realizar tarefas em situações do cotidiano.", "o": "Ginástica de condicionamento físico •Capacidades físicas voltadas para a promoção da saúde e aprimoramento funcional; •Desenvolvimento das capacidades físicas para a realização eficiente de tarefas diárias, promovendo autonomia e bem-estar; • Atividades relacionadas às capacidades físicas abordadas, além das respostas corporais que eles provocam (ex.: suor, alteração da frequência cardíaca, alteração da temperatura corporal etc.)."}, {"a": "7", "t": "1", "c": "EF67EF09-07/ES", "e": "", "h": "Construir, coletivamente, procedimentos e normas de convívio que viabilizem a participação de todos na prática de exercícios físicos, com o objetivo de promover a saúde. Enfatizando processos que levem os estudantes a reconhecerem que existem diferenças de condicionamento físico entre eles e propor atividades que sejam adequadas a todos.", "o": "Ginástica de condicionamento físico •Adaptação de exercícios para respeitar as limitações individuais, garantindo a participação de todos e promovendo a saúde."}, {"a": "7", "t": "1", "c": "EF67EF10", "e": "Ginásticas", "h": "Diferenciar exercício físico de atividade física e propor alternativas para a prática de exercícios físicos dentro e fora do ambiente escolar.", "o": "Ginástica de condicionamento físico •Diferenciação entre Exercício Físico e Atividade Física; •Exploração de formas acessíveis e criativas de realizar exercícios físicos no cotidiano, considerando os recursos disponíveis dentro e fora do ambiente escolar."}, {"a": "7", "t": "2", "c": "EF67EF04", "e": "Esportes", "h": "Praticar um ou mais esportes de marca, precisão, invasão e técnico-combinatórios oferecidos pela escola, usando habilidades técnico-táticas básicas e respeitando regras.", "o": "Esportes de Invasão •Regras; •Fundamentos básicos (técnico-tático) dos esportes trabalhados; •Simulações de jogo para aplicar fundamentos técnicos e táticos, compreendendo as dinâmicas dos esportes de invasão."}, {"a": "7", "t": "2", "c": "EF67EF14", "e": "Lutas", "h": "Experimentar, fruir e recriar diferentes lutas do Brasil, valorizando a própria segurança e integridade física, bem como as dos demais.", "o": "Lutas do Brasil •Tarracá, Jiu-Jitsu Brasileiro, Capoeira, Maculelê, Luta Marajoara, entre outras; •Cuidados e segurança durante a execução das lutas; •Modalidades (curta, média e longa distância)."}, {"a": "7", "t": "2", "c": "EF67EF15", "e": "Lutas", "h": "Planejar e utilizar estratégias básicas das lutas do Brasil, respeitando o colega como oponente.", "o": "Lutas do Brasil •Desenvolvimento da leitura de movimento e antecipação para identificar oportunidades nas lutas, priorizando o respeito e a segurança do/a colega."}, {"a": "7", "t": "2", "c": "EF67EF16", "e": "Lutas", "h": "Identificar as características (códigos, rituais, elementos técnico-táticos, indumentária, materiais, instalações, instituições) das lutas do Brasil.", "o": "Lutas do Brasil •Elementos constitutivos das lutas do Brasil (códigos, rituais, elementos técnico-táticos, indumentária, materiais, instalações, instituições); •Análise da diversidade regional das lutas do Brasil, destacando como as influências culturais locais moldam as práticas, os rituais e os estilos de luta."}, {"a": "7", "t": "2", "c": "EF67EF17", "e": "Lutas", "h": "Problematizar preconceitos e estereótipos relacionados ao universo das lutas e demais práticas corporais, propondo alternativas para superá-los, com base na solidariedade, na justiça, na equidade e no respeito.", "o": "Lutas do Brasil •Origem e herança cultural; •Racismo e exclusão social atrelados às lutas; •Comportamentos preconceituosos/ injustos relacionados às lutas brasileiras; •Problematização das lutas como atividade ligada ao universo masculino."}, {"a": "7", "t": "3", "c": "EF67EF01/ES", "e": "Brincadeiras e jogos", "h": "Experimentar e fruir, na escola e fora dela, jogos eletrônicos diversos e de diferentes gêneros, valorizando e respeitando os sentidos e significados atribuídos a eles por diferentes grupos sociais e etários.", "o": "Jogos eletrônicos •Jogos eletrônicos individuais e de interação coletiva com ênfase nos que envolvam o corpo em movimento; •Análise dos aspectos culturais e sociais dos jogos eletrônicos, promovendo respeito e inclusão entre diferentes gêneros e grupos etários."}, {"a": "7", "t": "3", "c": "EF67EF02", "e": "Brincadeiras e jogos", "h": "Identificar as transformações nas características dos jogos eletrônicos em função dos avanços das tecnologias e nas respectivas exigências corporais colocadas por esses diferentes tipos de jogos.", "o": "Jogos eletrônicos •Caracterização de diferentes tipos de jogos eletrônicos; •Influência dos jogos eletrônicos no sedentarismo; •Análise da influência dos jogos eletrônicos na dependência tecnológica."}, {"a": "7", "t": "3", "c": "EF67EF11-07/ES", "e": "", "h": "Experimentar, fruir e recriar danças urbanas, identificando seus elementos constitutivos (ritmo, espaço, gestos) bem como capacidades físicas durante as práticas das danças, utilizando-as como fator de ampliação de repertório motor dos estudantes. Promovendo aprendizagens sobre o percurso histórico das danças urbanas que são praticadas nos dias de hoje.", "o": "Danças urbanas •Hip Hop, Funk, Freestyle, Passinho e outros; •Elementos constitutivos da dança urbana (ritmo e expressão corporal; tempo, organização espacial e marcação musical)."}, {"a": "7", "t": "3", "c": "EF67EF12", "e": "Danças", "h": "Planejar e utilizar estratégias para aprender elementos constitutivos das danças urbanas.", "o": "Danças urbanas •Criação de sequências coreográficas que integrem os elementos das danças urbanas, promovendo a criatividade e a expressão individual."}, {"a": "7", "t": "3", "c": "EF67EF13/ES", "e": "", "h": "Diferenciar as danças urbanas das demais manifestações da dança, valorizando e respeitando os sentidos e significados atribuídos a eles por diferentes grupos sociais. Há, aqui, oportunidade de trabalho interdisciplinar com o componente curricular da Arte, no que se refere à investigação de diferentes tipos de dança.", "o": "Danças urbanas • Aspectos do contexto sociocultural (ritmos, passos básicos, expressão corporal, espaços, vestimentas) das danças urbanas e sua diferenciação das demais manifestações de dança; • Análise dos aspectos históricos e culturais que diferenciam as danças urbanas de outras formas de dança, ressaltando a valorização da diversidade cultural."}, {"a": "7", "t": "3", "c": "EF67EF18-07/ES", "e": "Práticas corporais de aventura", "h": "Experimentar e fruir diferentes práticas corporais de aventura urbanas, que não façam parte do contexto social dos estudantes, valorizando a própria segurança e integridade física, bem como as dos demais.", "o": "Práticas corporais de aventura urbanas •Parkour, Rapel, Skate, Slackline e outros; •Cuidados/Riscos relacionados à prática; •Limites corporais e superação do receio da realização da prática de uma determina prática de aventura; •Adaptação de espaços para a prática."}, {"a": "7", "t": "3", "c": "EF67EF19", "e": "Práticas corporais de aventura", "h": "Identificar os riscos durante a realização de práticas corporais de aventura urbanas e planejar estratégias para sua superação.", "o": "Práticas corporais de aventura urbanas •Equipamentos de segurança necessários para a prática de cada modalidade; •Importância da preparação física e mental, incluindo aquecimento, alongamento e técnicas de respiração, para minimizar riscos nas práticas de aventura urbanas. •Riscos envolvidos nas práticas corporais de aventura no meio urbano;"}, {"a": "7", "t": "3", "c": "EF67EF20", "e": "Práticas corporais de aventura", "h": "Executar práticas corporais de aventura urbanas, respeitando o patrimônio público e utilizando alternativas para a prática segura em diversos espaços.", "o": "Práticas corporais de aventura urbanas •Exploração de espaços urbanos adequados para atividades de aventura, enfatizando segurança, legalidade e respeito ao patrimônio público, promovendo consciência cidadã."}, {"a": "7", "t": "3", "c": "EF67EF21", "e": "Práticas corporais de aventura", "h": "Identificar a origem das práticas corporais de aventura e as possibilidades de recriá-las, reconhecendo as características (instrumentos, equipamentos de segurança, indumentária, organização) e seus tipos de práticas.", "o": "Práticas corporais de aventura urbanas •Definição e caracterização das práticas; •Análise das influências culturais e sociais que moldam as práticas de aventura, incluindo tradições locais e sua adaptação aos contextos urbanos; •Evolução tecnológica dos itens de segurança e equipamentos."}, {"a": "8", "t": "1", "c": "EF89EF01/ES", "e": "", "h": "Experimentar diferentes papéis (jogador, árbitro e técnico) e fruir os esportes de rede/parede, campo e taco, invasão e combate, valorizando o trabalho coletivo e o protagonismo. A experimentação de diferentes papéis nos esportes possibilita explorar situações de aprendizagem nas quais os estudantes exercitem o senso de justiça, o diálogo e a alteridade.", "o": "Esportes de Invasão •Esportes de invasão (Basquetebol, frisbee, futebol, futsal, futebol americano, handebol, hóquei, rúgbi, entre outros); •Vivência de outros papéis vinculados ao esporte."}, {"a": "8", "t": "1", "c": "EF89EF02", "e": "Esportes", "h": "Praticar um ou mais esportes de rede/parede, campo e taco, invasão e combate oferecidos pela escola, usando habilidades técnico-táticas básicas.", "o": "Esportes de Invasão •Técnicas de fundamentos básicos dos esportes de invasão, como dribles, passes, arremessos e movimentação, enfatizando sua aplicação prática nas situações de jogo."}, {"a": "8", "t": "1", "c": "EF89EF03", "e": "Esportes", "h": "Formular e utilizar estratégias para solucionar os desafios técnicos e táticos, tanto nos esportes de campo e taco, rede/parede, invasão e combate como nas modalidades esportivas escolhidas para praticar de forma específica.", "o": "Esportes de Invasão •Análise de situações de jogo para identificar oportunidades e desafios, formulando táticas para superá-los, como posicionamento em campo/quadra e movimentação em equipe."}, {"a": "8", "t": "1", "c": "EF89EF04", "e": "Esportes", "h": "Identificar os elementos técnicos ou técnico táticos individuais, combinações táticas, sistemas de jogo e regras das modalidades esportivas praticadas, bem como diferenciar as modalidades esportivas com base nos critérios da lógica interna das categorias de esporte: rede/parede, campo e taco, invasão e combate.", "o": "Esportes de Invasão •Análise das características dos esportes de invasão, enfocando a dinâmica de posse de bola, movimentação sem a bola e uso do espaço, além da colaboração entre jogadores/as e sua influência nas estratégias coletivas."}, {"a": "8", "t": "1", "c": "EF89EF05", "e": "Esportes", "h": "Identificar as transformações históricas do fenômeno esportivo e discutir alguns de seus problemas (doping, corrupção, violência, etc.) e a forma como as mídias os apresentam.", "o": "Esportes de Invasão •Transformações históricas do fenômeno esportivo; •Exclusão e invisibilidade feminina nos esportes; •Racismo no esporte e na mídia; •Influência das mídias sociais e tradicionais na percepção dos esportes de invasão."}, {"a": "8", "t": "1", "c": "EF89EF06", "e": "Esportes", "h": "Verificar locais disponíveis na comunidade para a prática de esportes e das demais práticas corporais tematizadas na escola, propondo e produzindo alternativas para utilizá-los no tempo livre.", "o": "Esportes de Invasão •Identificação de equipamentos e materiais necessários para a prática segura dos esportes de invasão nos espaços comunitários."}, {"a": "8", "t": "1", "c": "EF89EF16", "e": "Lutas", "h": "Experimentar e fruir a execução dos movimentos pertencentes às lutas do mundo, adotando procedimentos de segurança e respeitando o oponente.", "o": "Lutas do mundo •Lutas de diferentes lugares do mundo (aikido, kung fu, wing chun, kendo, judô, boxe, karatê, muay thai, esgrima, luta greco-romana, entre outros); •Discussão sobre a importância do respeito e da ética nas lutas, promovendo um ambiente seguro e saudável para todos/as os/as praticantes."}, {"a": "8", "t": "1", "c": "EF89EF17", "e": "Lutas", "h": "Planejar e utilizar estratégias básicas das lutas experimentadas, reconhecendo as suas características técnico-táticas.", "o": "Lutas do mundo •Análise das características técnico-táticas específicas de cada modalidade de luta, incluindo posições, movimentos e combinações; •Reflexão sobre como adaptar as estratégias de luta para diferentes contextos e oponentes, promovendo a flexibilidade tática."}, {"a": "8", "t": "1", "c": "EF89EF18", "e": "Lutas", "h": "Discutir as transformações históricas, o processo de esportivização e a midiatização de uma ou mais lutas, valorizando e respeitando as culturas de origem.", "o": "Lutas do mundo •Características e transformações históricas das lutas estudadas; •Processo de esportivização das lutas; •Influência da mídia nas competições de lutas; •Diferenciação entre luta, arte marcial e esporte de combate; •Filosofia das lutas."}, {"a": "8", "t": "2", "c": "EF89EF07-08/ES", "e": "", "h": "Experimentar e fruir um ou mais programas de exercícios físicos, inicialmente investigando e experimentando programas e tipos de exercícios físicos existentes, identificando as exigências corporais desses diferentes programas e reconhecendo a importância de uma prática individualizada, adequada às características e necessidades de cada sujeito.", "o": "Ginástica de condicionamento físico •Ginásticas de condicionamento físico (calistenia, musculação, jump, step, ginástica localizada, treinamento funcional, entre outros); •Diferenciação entre os objetivos de cada programa (perda de peso, ganho de massa muscular, aumento da resistência cardiovascular, etc.); •Associação das características, necessidades e interesses de cada sujeito ao programa mais adequado."}, {"a": "8", "t": "2", "c": "EF89EF08", "e": "Ginásticas", "h": "Discutir as transformações históricas dos padrões de desempenho, saúde e beleza, considerando a forma como são apresentados nos diferentes meios (científico, midiático etc.).", "o": "Ginástica de condicionamento físico •Evolução histórica dos padrões de desempenho, saúde e beleza; • Impacto da indústria da saúde e do fitness na formação de conceitos sobre desempenho físico e estética; •Conceito de beleza e marginalização de corpos negros e indígenas; •Relação entre saúde física, mental e a pressão estética imposta por padrões midiáticos."}, {"a": "8", "t": "2", "c": "EF89EF09", "e": "Ginásticas", "h": "Problematizar a prática excessiva de exercícios físicos e o uso de medicamentos para a ampliação do rendimento ou potencialização das transformações corporais.", "o": "Ginástica de condicionamento físico •Transtornos de imagem corporal e seus impactos na saúde; •Discussão sobre a ética no uso de medicamentos e suplementos no contexto esportivo e fitness; •Problematização do uso de medicamentos e suplementação; •Alternativas saudáveis para a melhoria do condicionamento físico, enfatizando a importância de um estilo de vida equilibrado."}, {"a": "8", "t": "2", "c": "EF89EF10-08/ES", "e": "Ginásticas", "h": "Experimentar e fruir um ou mais tipos de ginástica de conscientização corporal, que os estudantes conheçam ou pratiquem, identificando as exigências corporais dos mesmos.", "o": "Ginástica de conscientização corporal •Ginásticas de conscientização corporal (yoga, thai chi chuan, pilates, meditação) e exigências corporais relacionadas."}, {"a": "8", "t": "2", "c": "EF89EF11", "e": "Ginásticas", "h": "Identificar as diferenças e semelhanças entre a ginástica de conscientização corporal e as de condicionamento físico e discutir como a prática de cada uma dessas manifestações pode contribuir para a melhoria das condições de vida, saúde, bem-estar e cuidado consigo mesmo.", "o": "Ginástica de conscientização corporal •Conscientização corporal e condicionamento físico: definição, objetivos, elementos e características; •Benefícios dessas práticas para as qualidades de vida, saúde, bem-estar e cuidado consigo mesmo; •Reflexão sobre a percepção corporal e como ela pode impactar a autoestima e a autoconfiança."}, {"a": "8", "t": "3", "c": "EF89EF12/ES", "e": "Danças", "h": "Experimentar, fruir e recriar danças de salão, valorizando a diversidade cultural e respeitando a tradição dessas culturas. Há, aqui, oportunidade de trabalho interdisciplinar com o componente curricular da Arte, no que se refere à experimentação e fruição de diversos tipos de dança.", "o": "Danças de salão •Danças de salão (forró, samba de gafieira, zouk, salsa, cumbia, valsa, kizomba, bolero, bachata, xote, maxixe, soltinho, lambada, entre outros)."}, {"a": "8", "t": "3", "c": "EF89EF13/ES", "e": "Danças", "h": "Planejar e utilizar estratégias para se apropriar dos elementos constitutivos (ritmo, espaço, gestos) das danças de salão. O estudo do elemento constituinte espaço possibilita interações com o componente curricular Geografia.", "o": "Danças de salão •Elementos que compõem as danças de salão trabalhadas, como passos, ritmos, estilos, espaços e vestimentas."}, {"a": "8", "t": "3", "c": "EF89EF14/ES", "e": "Danças", "h": "Discutir estereótipos e preconceitos relativos às danças de salão e demais práticas corporais e propor alternativas para sua superação. Há, aqui, oportunidade de trabalho interdisciplinar com Arte, no que se refere à problematização de estereótipos e preconceitos relacionados às práticas corporais.", "o": "Danças de salão •Estereótipos sobre os papéis de gênero tradicionalmente estabelecidos nas danças de salão; •Variações regionais das danças de salão e histórico de opressões ou marginalização racial, particularmente de culturas afrodescendentes; •Uso de músicas e estilos de dança que reflitam a diversidade cultural e social, representando diferentes grupos étnicos e classes sociais; •Diversidade e inclusão nas danças de salão."}, {"a": "8", "t": "3", "c": "EF89EF15", "e": "Danças", "h": "Analisar as características (ritmos, gestos, coreografias e músicas) das danças de salão, bem como suas transformações históricas e os grupos de origem.", "o": "Danças de salão •Discussão sobre os grupos sociais que originaram e popularizaram as danças de salão, incluindo aspectos de classe, etnia e cultura; •Exame das transformações nas danças de salão ao longo do tempo, considerando mudanças nos estilos, ritmos e contextos sociais."}, {"a": "8", "t": "3", "c": "EF89EF19-08/ES", "e": "Práticas corporais de aventura", "h": "Experimentar e fruir diferentes práticas corporais de aventura na natureza, partindo de modalidades com exigências mais simples, valorizando a própria segurança e integridade física, bem como as dos demais, respeitando o patrimônio natural e minimizando os impactos de degradação ambiental.", "o": "Práticas corporais de aventura na natureza •Práticas corporais de aventura na natureza (arborismo, trekking, escalada, corrida de orientação/aventura, rapel, stand up paddle, slackline/waterline, sandboard, kitesurf, surfe, bodyboard, entre outros), enfatizando os cuidados durante a prática; •Educação ambiental e sustentabilidade; •Responsabilidade ambiental."}, {"a": "8", "t": "3", "c": "EF89EF20", "e": "Práticas corporais de aventura", "h": "Identificar riscos, formular estratégias e observar normas de segurança para superar os desafios na realização de práticas corporais de aventura na natureza.", "o": "Práticas corporais de aventura na natureza •Riscos e normas de segurança nas práticas abordadas; •Discussão sobre a importância da hidratação e nutrição antes, durante e após as atividades de aventura."}, {"a": "8", "t": "3", "c": "EF89EF21", "e": "Práticas corporais de aventura", "h": "Identificar as características (equipamentos de segurança, instrumentos, indumentária, organização) das práticas corporais de aventura na natureza, bem como suas transformações históricas.", "o": "Práticas corporais de aventura na natureza •Caracterização das práticas de aventura abordadas: organização, equipamentos de segurança, vestimentas; •Histórico das práticas corporais de aventura, destacando marcos significativos, influências culturais e a evolução das técnicas e equipamentos utilizados."}, {"a": "9", "t": "1", "c": "EF89EF01/ES", "e": "", "h": "Experimentar diferentes papéis (jogador, árbitro e técnico) e fruir os esportes de rede/parede, campo e taco, invasão e combate, valorizando o trabalho coletivo e o protagonismo. A experimentação de diferentes papéis nos esportes possibilita explorar situações de aprendizagem nas quais os estudantes exercitem o senso de justiça, o diálogo e a alteridade.", "o": "Esportes de Rede e Parede •Esportes de rede/parede (Voleibol, tênis de campo, tênis de mesa, badminton, peteca, voleibol de praia, punhobol, raquetebol, squash, beach tênis, entre outros); •Vivência de outros papéis vinculados ao esporte."}, {"a": "9", "t": "1", "c": "EF89EF02", "e": "Esportes", "h": "Praticar um ou mais esportes de rede/parede, campo e taco, invasão e combate oferecidos pela escola, usando habilidades técnico-táticas básicas.", "o": "Esportes de Rede e Parede •Técnicas de fundamentos básicos dos esportes de rede e parede, enfatizando sua aplicação prática nas situações de jogo."}, {"a": "9", "t": "1", "c": "EF89EF03", "e": "Esportes", "h": "Formular e utilizar estratégias para solucionar os desafios técnicos e táticos, tanto nos esportes de campo e taco, rede/parede, invasão e combate como nas modalidades esportivas escolhidas para praticar de forma específica.", "o": "Esportes de Rede e Parede •Análise de situações de jogo para identificar oportunidades e desafios, formulando táticas para superá-los, como posicionamento em campo/quadra e movimentação."}, {"a": "9", "t": "1", "c": "EF89EF04", "e": "Esportes", "h": "Identificar os elementos técnicos ou técnico-táticos individuais, combinações táticas, sistemas de jogo e regras das modalidades esportivas praticadas, bem como diferenciar as modalidades esportivas com base nos critérios da lógica interna das categorias de esporte: rede/parede, campo e taco, invasão e combate.", "o": "Esportes de Rede e Parede •Identificação das combinações táticas e sistemas de jogo nos esportes de rede e parede; •Exploração das variações nas regras e suas implicações na dinâmica de jogo nos esportes de rede e parede."}, {"a": "9", "t": "1", "c": "EF89EF06", "e": "Esportes", "h": "Verificar locais disponíveis na comunidade para a prática de esportes e das demais práticas corporais tematizadas na escola, propondo e produzindo alternativas para utilizá-los no tempo livre.", "o": "Esportes de Rede e Parede •Identificação de equipamentos e materiais necessários para a prática segura dos esportes de rede e parede nos espaços comunitários."}, {"a": "9", "t": "1", "c": "EF89EF16", "e": "Lutas", "h": "Experimentar e fruir a execução dos movimentos pertencentes às lutas do mundo, adotando procedimentos de segurança e respeitando o oponente.", "o": "Lutas do mundo •Lutas de diferentes lugares do mundo (aikido, kung fu, wing chun, kendo, judô, boxe, karatê, muay thai, esgrima, luta greco-romana, entre outros); •Discussão sobre a importância do respeito e da ética nas lutas, promovendo um ambiente seguro e saudável para todos/as os/as praticantes."}, {"a": "9", "t": "1", "c": "EF89EF17", "e": "Lutas", "h": "Planejar e utilizar estratégias básicas das lutas experimentadas, reconhecendo as suas características técnico-táticas.", "o": "Lutas do mundo •Análise das características técnico-táticas específicas de cada modalidade de luta, incluindo posições, movimentos e combinações; •Reflexão sobre como adaptar as estratégias de luta para diferentes contextos e oponentes, promovendo a flexibilidade tática."}, {"a": "9", "t": "1", "c": "EF89EF18", "e": "Lutas", "h": "Discutir as transformações históricas, o processo de esportivização e a midiatização de uma ou mais lutas, valorizando e respeitando as culturas de origem.", "o": "Lutas do mundo •Características e transformações históricas das lutas estudadas; •Processo de esportivização das lutas; •Influência da mídia nas competições de lutas; •Diferenciação entre luta, arte marcial e esporte de combate; •Filosofia das lutas."}, {"a": "9", "t": "2", "c": "EF89EF07-09/ES", "e": "", "h": "Experimentar e fruir um ou mais programas de exercícios físicos, identificando as exigências corporais desses diferentes programas e reconhecendo a importância de uma prática individualizada, adequada às características e necessidades de cada sujeito. A partir das experiências e expectativas vivenciadas no ano anterior, propor sequências de atividades individualizadas para que pratiquem individualmente e coletivamente.", "o": "Ginástica de condicionamento físico •Ginásticas de condicionamento físico (calistenia, musculação, jump, step, ginástica localizada, treinamento funcional, entre outros); •Diferenciação entre os objetivos de cada programa (perda de peso, ganho de massa muscular, aumento da resistência cardiovascular etc.); •Associação das características, necessidades e interesses de cada sujeito ao programa mais adequado."}, {"a": "9", "t": "2", "c": "EF89EF08", "e": "Ginásticas", "h": "Discutir as transformações históricas dos padrões de desempenho, saúde e beleza, considerando a forma como são apresentados nos diferentes meios (científico, midiático etc.).", "o": "Ginástica de condicionamento físico •Evolução histórica dos padrões de desempenho, saúde e beleza; •Impacto da indústria da saúde e do fitness na formação de conceitos sobre desempenho físico e estética; •Conceito de beleza e marginalização de corpos negros e indígenas; •Relação entre saúde física, mental e a pressão estética imposta por padrões midiáticos."}, {"a": "9", "t": "2", "c": "EF89EF09", "e": "Ginásticas", "h": "Problematizar a prática excessiva de exercícios físicos e o uso de medicamentos para a ampliação do rendimento ou potencialização das transformações corporais.", "o": "Ginástica de condicionamento físico •Transtornos de imagem corporal e seus impactos na saúde; •Discussão sobre a ética no uso de medicamentos e suplementos no contexto esportivo e fitness; •Problematização do uso de medicamentos e suplementação; •Alternativas saudáveis para a melhoria do condicionamento físico, enfatizando a importância de um estilo de vida equilibrado."}, {"a": "9", "t": "2", "c": "EF89EF10-09/ES", "e": "Ginásticas", "h": "Experimentar e fruir um ou mais tipos de ginástica de conscientização corporal, menos familiares aos estudantes, identificando as exigências corporais dos mesmos.", "o": "Ginástica de conscientização corporal •Ginásticas de conscientização corporal (yoga, thai chi chuan, pilates, meditação) e exigências corporais relacionadas; •Atividades práticas para explorar a conexão mentecorpo em cada uma das modalidades."}, {"a": "9", "t": "2", "c": "EF89EF11", "e": "Ginásticas", "h": "Identificar as diferenças e semelhanças entre a ginástica de conscientização corporal e as de condicionamento físico e discutir como a prática de cada uma dessas manifestações pode contribuir para a melhoria das condições de vida, saúde, bem-estar e cuidado consigo mesmo.", "o": "Ginástica de conscientização corporal •Conscientização corporal e condicionamento físico: definição, objetivos, elementos e características; •Benefícios dessas práticas para as qualidades de vida, saúde, bem-estar e cuidado consigo mesmo; •Reflexão sobre a percepção corporal e como ela pode impactar a autoestima e a autoconfiança."}, {"a": "9", "t": "2", "c": "EF89EF12/ES", "e": "Danças", "h": "Experimentar, fruir e recriar danças de salão, valorizando a diversidade cultural e respeitando a tradição dessas culturas. Há, aqui, oportunidade de trabalho interdisciplinar com o componente curricular da Arte, no que se refere à experimentação e fruição de diversos tipos de dança.", "o": "Danças de salão •Danças de salão (forró, samba de gafieira, zouk, salsa, cumbia, valsa, kizomba, bolero, bachata, xote, maxixe, soltinho, lambada, entre outros)."}, {"a": "9", "t": "2", "c": "EF89EF13/ES", "e": "Danças", "h": "Planejar e utilizar estratégias para se apropriar dos elementos constitutivos (ritmo, espaço, gestos) das danças de salão. O estudo do elemento constituinte espaço possibilita interações com o componente curricular Geografia.", "o": "Danças de salão •Elementos que compõem as danças de salão trabalhadas, como passos, ritmos, estilos, espaços e vestimentas."}, {"a": "9", "t": "2", "c": "EF89EF14/ES", "e": "", "h": "Discutir estereótipos e preconceitos relativos às danças de salão e demais práticas corporais e propor alternativas para sua superação. Há, aqui, oportunidade de trabalho interdisciplinar com Arte, no que se refere à problematização de estereótipos e preconceitos relacionados às práticas corporais. Há oportunidade de trabalho com Língua Portuguesa.", "o": "Danças de salão •Estereótipos sobre os papéis de gênero tradicionalmente estabelecidos nas danças de salão; •Variações regionais das danças de salão e histórico de opressões ou marginalização racial, particularmente de culturas afrodescendentes; •Uso de músicas e estilos de dança que reflitam a diversidade cultural e social, representando diferentes grupos étnicos e classes sociais; •Diversidade e inclusão nas danças de salão."}, {"a": "9", "t": "2", "c": "EF89EF15", "e": "Danças", "h": "Analisar as características (ritmos, gestos, coreografias e músicas) das danças de salão, bem como suas transformações históricas e os grupos de origem.", "o": "Danças de salão •Discussão sobre os grupos sociais que originaram e popularizaram as danças de salão, incluindo aspectos de classe, etnia e cultura; •Exame das transformações nas danças de salão ao longo do tempo, considerando mudanças nos estilos, ritmos e contextos sociais."}, {"a": "9", "t": "3", "c": "EF89EF05", "e": "Esportes", "h": "Identificar as transformações históricas do fenômeno esportivo e discutir alguns de seus problemas (doping, corrupção, violência, etc.) e a forma como as mídias os apresentam.", "o": "Esportes de Rede e Parede •Transformações históricas do fenômeno esportivo; •Representações Midiáticas e estereótipos de Gênero; •Racismo e desigualdade racial nos esportes; •Elitismo e exclusão social; •LGBTfobia nos esportes; •Violência e ética nos esportes."}, {"a": "9", "t": "3", "c": "EF89EF19-09/ES", "e": "Práticas corporais de aventura", "h": "Experimentar e fruir diferentes práticas corporais de aventura na natureza, com modalidades com exigências um pouco mais complexas, valorizando a própria segurança e integridade física, bem como as dos demais, respeitando o patrimônio natural e minimizando os impactos de degradação ambiental.", "o": "Práticas corporais de aventura na natureza •Práticas corporais de aventura na natureza (arborismo, trekking, escalada, corrida de orientação/aventura, rapel, stand up paddle, slackline/waterline, sandboard, kitesurf, surfe, bodyboard, entre outros), enfatizando os cuidados durante a prática; •Educação ambiental e sustentabilidade; •Princípios de respeito e cuidado com a biodiversidade durante as atividades, incluindo a observação de fauna e flora sem causar danos."}, {"a": "9", "t": "3", "c": "EF89EF20", "e": "Práticas corporais de aventura", "h": "Identificar riscos, formular estratégias e observar normas de segurança para superar os desafios na realização de práticas corporais de aventura na natureza.", "o": "Práticas corporais de aventura na natureza •Riscos e normas de segurança nas práticas abordadas; •Discussão sobre a importância da hidratação e nutrição antes, durante e após as atividades de aventura."}, {"a": "9", "t": "3", "c": "EF89EF21", "e": "Práticas corporais de aventura", "h": "Identificar as características (equipamentos de segurança, instrumentos, indumentária, organização) das práticas corporais de aventura na natureza, bem como suas transformações históricas.", "o": "Práticas corporais de aventura na natureza •Caracterização das práticas de aventura abordadas: organização, equipamentos de segurança, vestimentas; •Histórico das práticas corporais de aventura, destacando marcos significativos, influências culturais e a evolução das técnicas e equipamentos utilizados."}], "Ensino Religioso": [{"a": "6", "t": "1", "c": "EF06ER01", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer o papel da tradição escrita na preservação de memórias, acontecimentos e ensinamentos religiosos.", "o": "Tradição escrita: registro dos ensinamentos sagrados. •Conhecendo o sagrado pelos textos religiosos; •Textos religiosos e modos de vida; •Textos religiosos e interpretação."}, {"a": "6", "t": "1", "c": "EF06ER02", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer e valorizar a diversidade de textos religiosos escritos (textos do Budismo, Cristianismo, Espiritismo, Hinduísmo, Islamismo, Judaísmo, entre outros).", "o": "Tradição escrita: registro dos ensinamentos sagrados. •Conhecendo o sagrado pelos textos religiosos; •Textos religiosos e modos de vida; •Textos religiosos e interpretação."}, {"a": "6", "t": "2", "c": "EF06ER03", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer, em textos escritos, ensinamentos relacionados a modos de ser e viver evidenciando os códigos morais das religiões estudadas.", "o": "Ensinamentos da tradição escrita •Textos religiosos e interpretação (Possíveis tópicos a serem trabalhados: Livro de Mórmon, Codificação Espírita, Tradição oral do Candomblé, da Umbanda e de povos indígenas brasileiros, Tao Te Ching, Vedas, Bíblia, dentre outros); •Funções dos textos sagrados."}, {"a": "6", "t": "2", "c": "EF06ER04", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer que os textos escritos são utilizados pelas tradições religiosas de maneiras diversas.", "o": "Ensinamentos da tradição escrita •Textos religiosos e interpretação (Possíveis tópicos a serem trabalhados: Livro de Mórmon, Codificação Espírita, Tradição oral do Candomblé, da Umbanda e de povos indígenas brasileiros, Tao Te Ching, Vedas, Bíblia, dentre outros); •Funções dos textos sagrados."}, {"a": "6", "t": "2", "c": "EF06ER05", "e": "Crenças religiosas e filosofias de vida", "h": "Discutir como o estudo e a interpretação dos textos religiosos influenciam os adeptos a vivenciarem os ensinamentos das tradições religiosas, por exemplo, noções de \"Certo e errado\" / \"Bem e mal\".", "o": "Ensinamentos da tradição escrita •Textos religiosos e interpretação (Possíveis tópicos a serem trabalhados: Livro de Mórmon, Codificação Espírita, Tradição oral do Candomblé, da Umbanda e de povos indígenas brasileiros, Tao Te Ching, Vedas, Bíblia, dentre outros); •Funções dos textos sagrados."}, {"a": "6", "t": "3", "c": "EF06ER06", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer a importância dos mitos, ritos, símbolos e textos na estruturação das diferentes crenças, tradições e movimentos religiosos.", "o": "Símbolos, ritos e mitos religiosos •A linguagem simbólica – o conceito de símbolo; •Conceito de mito. •Os tipos de mito (Mitos heroicos, mitos de origem e de criação, mitos de fim do mundo e de morte, dentre outros.); •Conceito de rito; •Ritos religiosos e ritos seculares."}, {"a": "6", "t": "3", "c": "EF06ER07", "e": "Crenças religiosas e filosofias de vida", "h": "Exemplificar a relação entre mito, rito e símbolo nas práticas celebrativas de diferentes tradições religiosas.", "o": "Símbolos, ritos e mitos religiosos •A linguagem simbólica – o conceito de símbolo; •Conceito de mito. •Os tipos de mito (Mitos heroicos, mitos de origem e de criação, mitos de fim do mundo e de morte, dentre outros.); •Conceito de rito; •Ritos religiosos e ritos seculares."}, {"a": "7", "t": "1", "c": "EF07ER01", "e": "Manifestações religiosas", "h": "Reconhecer e respeitar as práticas de comunicação com as divindades em distintas manifestações e tradições religiosas.", "o": "Místicas e espiritualidades •Conceitos de mística e de experiências místicas; •Conceitos e práticas de espiritualidade; •Espiritualidade e religião; •O silêncio e a comunicação com as divindades (votos de silêncio, o Mauna, as danças dos povos indígenas, nas religiões afro-brasileiras, a dança dervixe, dentre outras)."}, {"a": "7", "t": "1", "c": "EF07ER02", "e": "Manifestações religiosas", "h": "Identificar práticas de espiritualidade utilizadas pelas pessoas em determinadas situações (acidentes, doenças, fenômenos climáticos, anseios pessoais e familiares e morte).", "o": "Místicas e espiritualidades •Conceitos de mística e de experiências místicas; •Conceitos e práticas de espiritualidade; •Espiritualidade e religião; •O silêncio e a comunicação com as divindades (votos de silêncio, o Mauna, as danças dos povos indígenas, nas religiões afro-brasileiras, a dança dervixe, dentre outras)."}, {"a": "7", "t": "2", "c": "EF07ER03", "e": "Manifestações religiosas", "h": "Reconhecer os papéis atribuídos às lideranças de diferentes tradições religiosas.", "o": "Lideranças religiosas •O conceito de liderança; •Formação de líderes; •Exemplos de grandes líderes e grandes líderes religiosos (Malala Yousafzai, Irmã Dorothy Stang, Moisés, papa Francisco, Chico Xavier, dentre outros); •Líderes religiosos das mais diversas religiões; •Lideranças religiosas e a busca pelo bem comum."}, {"a": "7", "t": "2", "c": "EF07ER04", "e": "Manifestações religiosas", "h": "Exemplificar líderes religiosos que se destacaram por suas contribuições à sociedade na busca pela cultura da paz.", "o": "Lideranças religiosas •O conceito de liderança; •Formação de líderes; •Exemplos de grandes líderes e grandes líderes religiosos (Malala Yousafzai, Irmã Dorothy Stang, Moisés, papa Francisco, Chico Xavier, dentre outros); •Líderes religiosos das mais diversas religiões; •Lideranças religiosas e a busca pelo bem comum."}, {"a": "7", "t": "2", "c": "EF07ER05", "e": "Manifestações religiosas", "h": "Discutir estratégias que promovam a convivência ética e respeitosa entre as religiões.", "o": "Lideranças religiosas •O conceito de liderança; •Formação de líderes; •Exemplos de grandes líderes e grandes líderes religiosos (Malala Yousafzai, Irmã Dorothy Stang, Moisés, papa Francisco, Chico Xavier, dentre outros); •Líderes religiosos das mais diversas religiões; •Lideranças religiosas e a busca pelo bem comum."}, {"a": "7", "t": "3", "c": "EF07ER06", "e": "Crenças religiosas e filosofias de vida", "h": "Identificar princípios éticos em diferentes tradições religiosas e filosofias de vida, discutindo como podem influenciar condutas pessoais e práticas sociais.", "o": "Princípios éticos e valores religiosos •O conceito de ética e moral; •Ética, moral, religião e valores religiosos; •Ética nas mais diversas religiões e filosofias de vida: dos povos indígenas, no Budismo, no Judaísmo, no Cristianismo, a ética do consenso e outras; •Ética global e religiões."}, {"a": "7", "t": "3", "c": "EF07ER07", "e": "Crenças religiosas e filosofias de vida", "h": "Identificar e discutir o papel das lideranças religiosas e seculares na defesa e promoção dos direitos humanos.", "o": "Lideranças e direitos humanos •O conceito de direitos humanos e a história dos direitos humanos; •As religiões e os direitos humanos; •Direitos humanos e respeito entre as religiões; •Líderes religiosos e seculares e a defesa dos direitos humanos."}, {"a": "7", "t": "3", "c": "EF07ER08", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer o direito à liberdade de consciência, crença ou convicção, questionando concepções e práticas sociais que a violam.", "o": "Lideranças e direitos humanos •O conceito de direitos humanos e a história dos direitos humanos; •As religiões e os direitos humanos; •Direitos humanos e respeito entre as religiões; •Líderes religiosos e seculares e a defesa dos direitos humanos."}, {"a": "8", "t": "1", "c": "EF08ER01", "e": "Crenças religiosas e filosofias de vida", "h": "Discutir como as crenças e convicções podem influenciar escolhas e atitudes pessoais e coletivas.", "o": "Crenças, convicções e atitudes •Sociedade Plural; •Valores pessoais e coletivos; •Crenças religiosas e princípios éticos; •Pespectivas não-religiosas: materialismo, agnosticismo, ateísmo, ceticismo, dentre outras; •Alteridade e respeito."}, {"a": "8", "t": "1", "c": "EF08ER02", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar filosofias de vida, manifestações e tradições religiosas destacando seus princípios éticos.", "o": "Crenças, convicções e atitudes •Sociedade Plural; •Valores pessoais e coletivos; •Crenças religiosas e princípios éticos; •Pespectivas não-religiosas: materialismo, agnosticismo, ateísmo, ceticismo, dentre outras; •Alteridade e respeito."}, {"a": "8", "t": "2", "c": "EF08ER03", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar doutrinas das diferentes tradições religiosas e suas concepções de mundo, vida e morte.", "o": "Doutrinas religiosas •Diversos conceitos de pessoa nas mais diversas religiões e filosofias de vida; •Conceitos de mundo nas mais diversas religiões e filosofias de vida; •Conceitos de vida e de existência nas mais diversas religiões e filosofias de vida; •Conceitos de morte nas mais diversas religiões e filosofias de vida; •Ancestralidade e culto aos antepassados."}, {"a": "8", "t": "2", "c": "EF08ER04", "e": "Crenças religiosas e filosofias de vida", "h": "Discutir como filosofias de vida, tradições e instituições religiosas podem influenciar diferentes campos da esfera pública (política, saúde, educação, economia).", "o": "Crenças, filosofias de vida e esfera pública •Esferas Públicas e Privadas; •Sociedade Plural; •Sociedade, Estado e religião; •Estados teocráticos e Estados Laicos; •Liberdade de pensamento, consciência e religião; •Pespectivas não-religiosas: materialismo, agnosticismo, ateísmo, ceticismo, dentre outros."}, {"a": "8", "t": "2", "c": "EF08ER05", "e": "Crenças religiosas e filosofias de vida", "h": "Debater sobre as possibilidades e os limites da interferência das tradições religiosas na esfera pública, considerando que o Brasil é um país laico.", "o": "Crenças, filosofias de vida e esfera pública •Esferas Públicas e Privadas; •Sociedade Plural; •Sociedade, Estado e religião; •Estados teocráticos e Estados Laicos; •Liberdade de pensamento, consciência e religião; •Pespectivas não-religiosas: materialismo, agnosticismo, ateísmo, ceticismo, dentre outros."}, {"a": "8", "t": "3", "c": "EF08ER06", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar práticas, projetos e políticas públicas que contribuem para a promoção da liberdade de pensamento, crenças e convicções.", "o": "Crenças, filosofias de vida e esfera pública •A democracia e a diversidade de crenças, filosofias de vida e religião."}, {"a": "8", "t": "3", "c": "EF08ER07", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar as formas de uso das mídias e tecnologias pelas diferentes denominações religiosas.", "o": "Tradições religiosas, mídias e tecnologias •Comunicação e mídia; •Religião e artes; •Comunicação digital; •Ciber-religião."}, {"a": "9", "t": "1", "c": "EF09ER01", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar princípios e orientações para o cuidado da vida e nas diversas tradições religiosas, filosofias de vida e na ciência.", "o": "Imanência e transcendência. Religião e valorização da vida •Religião e ecologia; •Religião e sustentabilidade; •Respeito à vida e à dignidade humana; •Respeito à vida não-humana; •Religião e Bioética."}, {"a": "9", "t": "1", "c": "EF09ER02", "e": "Crenças religiosas e filosofias de vida", "h": "Discutir as diferentes expressões de valorização e de desrespeito à vida, por meio da análise de matérias nas diferentes mídias (problematizar assuntos contemporâneos como aborto, células tronco, eutanásia etc.).", "o": "Imanência e transcendência. Religião e valorização da vida •Religião e ecologia; •Religião e sustentabilidade; •Respeito à vida e à dignidade humana; •Respeito à vida não-humana; •Religião e Bioética."}, {"a": "9", "t": "2", "c": "EF09ER03", "e": "Crenças religiosas e filosofias de vida", "h": "Identificar sentidos do viver e do morrer em diferentes tradições religiosas, através do estudo de mitos fundantes.", "o": "Vida e morte •Mitos de origem da vida das mais diversas religiões; •Mitos de origem da morte das mais diversas religiões; •Concepções de além-morte: Reencarnação, ressurreição, transmigração, mortalidade ou imortalidade da alma, evolução do espírito e outros conceitos; •Ritos fúnebres religiosos e seculares; •Atitudes religiosas e seculares diante da morte."}, {"a": "9", "t": "2", "c": "EF09ER04", "e": "Crenças religiosas e filosofias de vida", "h": "Identificar concepções de vida e morte em diferentes tradições religiosas e filosofias de vida, por meio da análise de diferentes ritos fúnebres.", "o": "Vida e morte •Mitos de origem da vida das mais diversas religiões; •Mitos de origem da morte das mais diversas religiões; •Concepções de além-morte: Reencarnação, ressurreição, transmigração, mortalidade ou imortalidade da alma, evolução do espírito e outros conceitos; •Ritos fúnebres religiosos e seculares; •Atitudes religiosas e seculares diante da morte."}, {"a": "9", "t": "2", "c": "EF09ER05", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar as diferentes ideias de imortalidade elaboradas pelas tradições religiosas (ancestralidade, reencarnação, transmigração e ressurreição).", "o": "Vida e morte •Mitos de origem da vida das mais diversas religiões; •Mitos de origem da morte das mais diversas religiões; •Concepções de além-morte: Reencarnação, ressurreição, transmigração, mortalidade ou imortalidade da alma, evolução do espírito e outros conceitos; •Ritos fúnebres religiosos e seculares; •Atitudes religiosas e seculares diante da morte."}, {"a": "9", "t": "3", "c": "EF09ER06", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer a coexistência como uma atitude ética de respeito à vida e à dignidade humana.", "o": "Princípios e valores éticos •Valores éticos e sociedade; •Religião e convivência; •Respeitar é preciso; •Projetos sociais laicos e de iniciativa religiosa."}, {"a": "9", "t": "3", "c": "EF09ER07", "e": "Crenças religiosas e filosofias de vida", "h": "Identificar princípios éticos (familiares, religiosos e culturais) que possam alicerçar a construção de projetos de vida e a influência da religião na constituição dos valores sociais.", "o": "Princípios e valores éticos •Valores éticos e sociedade; •Religião e convivência; •Respeitar é preciso; •Projetos sociais laicos e de iniciativa religiosa."}, {"a": "9", "t": "3", "c": "EF09ER08", "e": "Crenças religiosas e filosofias de vida", "h": "Construir projetos de vida assentados em princípios e valores éticos.", "o": "Princípios e valores éticos •Valores éticos e sociedade; •Religião e convivência; •Respeitar é preciso; •Projetos sociais laicos e de iniciativa religiosa."}]};
